/* Sarisa y elefante · guiones.js
   Desarrollo histórico de cada batalla, para verla como observador: fases con comentario, cita de la fuente y los movimientos
   que la representan sobre el tablero. Lo reproduce observador.js.

   Cada fase: t título · c comentario · src clave de CITAS o de SOURCES (fuentes.js) · f fiabilidad · acc acciones.
   Fiabilidad:  f  lo cuenta la fuente
                m  el hecho está atestiguado; cómo ocurrió sobre el terreno es reconstrucción
                r  las fuentes callan: reconstrucción verosímil
                d  relato que ya se discutía en la Antigüedad
                u  una sola fuente, tardía o literaria
   Unidades: 'A3' es la unidad número 3 (contando desde 0) del primer bando en batallas.js; 'B0', la primera del segundo.
   Acciones:
     ['mv',['A3',x,y],…]            mueve a la vez las unidades indicadas
     ['at','A3','B4',daño,{…}]      ataque con resultado fijado. Opciones: c respuesta del defensor · push el defensor retrocede
                                    st casillas recorridas (2 o más = carga) · cine escena en 3D
     ['hit','B4',daño]              daño sin atacante (estampidas, proyectiles)
     ['out','B4',motivo]            la unidad sale del tablero: fled, withdraw, captured, fall, suicide, destroyed
     ['pasa','B4']                  la unidad se pasa al otro bando
     ['say','B4','texto|text']      rótulo sobre una unidad (o sobre varias: ['say',['A2','A3'],…])
   Tras tocar este archivo, ejecuta en la consola: await comprobarGuiones() */
"use strict";

/* Pasajes citados solo en el desarrollo histórico. El texto original está cotejado con las mismas ediciones que fuentes.js;
   urn indica el pasaje exacto con el que se ha comprobado. */
const SCA=urn=>PER(urn.split(':').slice(0,4).join(':')+':'+urn.split(':')[4].split('-')[0].split('.').slice(0,2).join('.'));
const DIO='urn:cts:greekLit:tlg0060.tlg001.perseus-grc6:',POL='urn:cts:greekLit:tlg0543.tlg001.perseus-grc2:',PLU='urn:cts:greekLit:tlg0007.tlg057.perseus-grc2:',
      LUC='urn:cts:greekLit:tlg0062.tlg057.perseus-grc2:',LIV='urn:cts:latinLit:phi0914.phi001.perseus-lat2:',MAC='urn:cts:greekLit:tlg0527.tlg023.1st1K-grc1:';
const CITAS={
  diod82:{ref:'Diodoro 19.82.3–4|Diodorus 19.82.3–4',lang:'grc',urn:DIO+'19.82.3-19.82.4',
    o:'τὸ μὲν οὖν εὐώνυμον κέρας οὕτω κατασκευάσας διενοεῖτο τούτῳ κρίνειν τὴν μάχην. […] ἐπὶ δὲ τὸ δεξιὸν κέρας ἔταξε τοὺς λοιποὺς ἱππεῖς χιλίους πεντακοσίους, ὧν Ἀνδρόνικος ἡγεῖτο. τούτῳ δʼ ἦν συντεταγμένον λοξὴν φυλάττειν τὴν στάσιν καὶ φυγομαχεῖν, καραδοκοῦντα τὴν διʼ αὐτοῦ γινομένην κρίσιν.',
    tr:'Dispuesta así el ala izquierda, pensaba decidir con ella la batalla. […] En el ala derecha colocó al resto de la caballería, mil quinientos jinetes, al mando de Andrónico. Este tenía orden de mantener la formación en oblicuo y rehuir el combate, a la espera de la decisión que él mismo iba a lograr.|Having thus arranged his left wing, he intended to decide the battle with it. […] On the right wing he posted the rest of the cavalry, fifteen hundred men, commanded by Andronicus. He had been ordered to keep his line oblique and avoid battle, awaiting the decision that Demetrius himself would bring about.'},
  diod83b:{ref:'Diodoro 19.83.3–4|Diodorus 19.83.3–4',lang:'grc',urn:DIO+'19.83.3-19.83.4',
    o:'Ἀντεπαγόντων δὲ καὶ τῶν ἐναντίων τὸ μὲν πρῶτον ἐπʼ ἄκρων τῶν κεράτων ἱππομαχία συνέστη τῶν προτεταγμένων ἱππέων, ἐν οἷς πολὺ προετέρουν οἱ περὶ τὸν Δημήτριον. μετʼ ὀλίγον δὲ τῶν περὶ Πτολεμαῖον καὶ Σέλευκον περιιππευσάντων τὸ κέρας καὶ βιαιότερον ἐπενεχθέντων ὀρθαῖς ταῖς εἴλαις συνέστη καρτερὰ μάχη διὰ τὰς ἑκατέρων προθυμίας.',
    tr:'Cuando también los contrarios avanzaron a su encuentro, se trabó primero, en el extremo de las alas, un combate de caballería entre los jinetes de vanguardia, en el que los de Demetrio llevaban mucha ventaja. Pero poco después, cuando los de Ptolomeo y Seleuco rodearon el ala a caballo y cargaron con más violencia, con los escuadrones en columna, se entabló una lucha encarnizada por el ardor de unos y otros.|When their opponents also advanced to meet them, there was first a cavalry fight at the tips of the wings between the horsemen of the advance guards, in which Demetrius’ men had much the better of it. But soon afterwards, when Ptolemy and Seleucus rode around the wing and charged more violently with their squadrons in column, a fierce battle developed through the ardour of both sides.'},
  diod84a:{ref:'Diodoro 19.84.1|Diodorus 19.84.1',lang:'grc',urn:DIO+'19.84.1',
    o:'ἐπὶ πολὺν δὲ χρόνον τῆς ἱππομαχίας οὔσης ἐφαμίλλου τὰ θηρία διὰ τῶν Ἰνδῶν εἰς τὸν ἀγῶνα παρορμηθέντα μέχρι μέν τινος προῆγεν καταπληκτικῶς, ὡς οὐδενὸς ὑποστησομένου· ὡς δʼ ἐπὶ τὸν σεσιδηρωμένον χάρακα κατήντησε, τὸ μὲν πλῆθος τῶν ἀκοντιστῶν καὶ τοξοτῶν συνεχῶς βαλλόντων κατετίτρωσκε τὰ σώματα τῶν ἐλεφάντων καὶ τοὺς ἐπʼ αὐτοῖς ἀναβεβηκότας·',
    tr:'Como el combate de caballería se mantenía igualado durante mucho tiempo, las fieras, azuzadas por los indios, avanzaron un trecho de manera aterradora, como si nadie fuera a resistirlas; pero, cuando llegaron a la empalizada guarnecida de hierro, la multitud de lanzadores de jabalina y arqueros, disparando sin cesar, hería los cuerpos de los elefantes y a quienes los montaban.|As the cavalry battle remained evenly balanced for a long time, the beasts, urged into the fight by the Indians, advanced for a while in a terrifying manner, as if no one would withstand them; but when they came to the iron-fitted palisade, the mass of javelin-men and archers, shooting without pause, kept wounding the bodies of the elephants and the men mounted on them.'},
  diod84b:{ref:'Diodoro 19.84.4–5|Diodorus 19.84.4–5',lang:'grc',urn:DIO+'19.84.4-19.84.5',
    o:'τέλος δὲ τῶν πλείστων Ἰνδῶν κατακοντισθέντων ὑποχειρίους συνέβη γενέσθαι πάντας τοὺς ἐλέφαντας. οὗ τελεσθέντος οἱ πολλοὶ τῶν περὶ τὸν Δημήτριον ἱππέων καταπλαγέντες πρὸς φυγὴν ὥρμησαν· αὐτὸς δὲ μετʼ ὀλίγων ἀπολειφθεὶς καὶ δεόμενος ἑκάστου στῆναι καὶ μὴ καταλιπεῖν αὐτόν, ὡς οὐδεὶς προσεἶχε, συναποχωρεῖν ἠναγκάζετο.',
    tr:'Al final, abatidos a jabalinazos la mayoría de los indios, todos los elefantes fueron capturados. Hecho esto, la mayor parte de la caballería de Demetrio, aterrada, se dio a la fuga; él, que se quedó con unos pocos y rogaba a cada uno que se detuviera y no lo abandonara, como nadie le hacía caso, se vio obligado a retirarse con ellos.|In the end, most of the Indians having been shot down, all the elephants were captured. When this happened, most of Demetrius’ cavalry took fright and turned to flight; he himself, left with a few men and begging each one to stand and not abandon him, since no one paid heed, was forced to withdraw with them.'},
  diod92a:{ref:'Diodoro 19.92.2|Diodorus 19.92.2',lang:'grc',urn:DIO+'19.92.2',
    o:'διαβὰς δὲ τὸν Τίγριν ποταμὸν καὶ πυνθανόμενος ὀλίγων ἡμερῶν ὁδὸν ἀπέχειν τοὺς πολεμίους, ἔκρυψε τοὺς στρατιώτας ἐν τοῖς πλησίον ἕλεσι, διανοούμενος ἀπροσδόκητον ποιήσασθαι τὴν ἐπίθεσιν.',
    tr:'Cruzó el río Tigris y, al saber que el enemigo estaba a pocos días de camino, ocultó a los soldados en los pantanos cercanos, con la intención de atacar por sorpresa.|He crossed the river Tigris and, learning that the enemy were a few days’ march away, hid his soldiers in the nearby marshes, intending to make his attack unexpected.'},
  diod92b:{ref:'Diodoro 19.92.5|Diodorus 19.92.5',lang:'grc',urn:DIO+'19.92.5',
    o:'ὁ δὲ Νικάνωρ μετʼ ὀλίγων ἀπολειφθεὶς καὶ δεδιὼς μὴ παραδοθῇ τοῖς πολεμίοις, ἔφυγε μετὰ τῶν φίλων διὰ τῆς ἐρήμου.',
    tr:'Nicanor, que se quedó con unos pocos y temía ser entregado al enemigo, huyó con sus amigos a través del desierto.|Nicanor, left with a few men and fearing that he would be handed over to the enemy, fled with his friends through the desert.'},
  plut28:{ref:'Plutarco, Demetrio 28.3|Plutarch, Demetrius 28.3',lang:'grc',urn:PLU+'28',
    o:'ἦγε δὲ πεζοὺς μὲν ἑπτακισμυρίων πλείους, ἱππεῖς δὲ μυρίους, ἐλέφαντας δὲ ἑβδομήκοντα πέντε, τῶν ἐναντίων ἐχόντων πεζοὺς μὲν ἑξακισμυρίους καὶ τετρακισχιλίους, ἱππεῖς δὲ πεντακοσίους τῶν ἐκείνου πλείονας, ἐλέφαντας δὲ τετρακοσίους, ἅρματα δὲ ἑκατὸν εἴκοσι.',
    tr:'Llevaba más de setenta mil infantes, diez mil jinetes y setenta y cinco elefantes, mientras que los contrarios tenían sesenta y cuatro mil infantes, quinientos jinetes más que él, cuatrocientos elefantes y ciento veinte carros.|He led more than seventy thousand foot, ten thousand horse and seventy-five elephants, while his opponents had sixty-four thousand foot, five hundred more horse than he, four hundred elephants and a hundred and twenty chariots.'},
  plut29i:{ref:'Plutarco, Demetrio 29.3|Plutarch, Demetrius 29.3',lang:'grc',urn:PLU+'29',
    o:'Δημήτριος ἔχων τοὺς πλείστους καὶ κρατίστους τῶν ἱππέων Ἀντιόχῳ τῷ Σελεύκου συνέπεσε, καὶ μέχρι τροπῆς τῶν πολεμίων λαμπρῶς ἀγωνισάμενος ἐν τῇ διώξει σοβαρᾷ καὶ φιλοτίμῳ παρὰ καιρὸν γενομένῃ τὴν νίκην διέφθειρεν.',
    tr:'Demetrio, con la mayor parte y lo mejor de la caballería, chocó con Antíoco, el hijo de Seleuco, y, tras combatir brillantemente hasta poner en fuga a los enemigos, echó a perder la victoria con una persecución arrogante y ambiciosa, emprendida a destiempo.|Demetrius, with the greater and best part of the cavalry, fell upon Antiochus the son of Seleucus and, after fighting brilliantly until the enemy were routed, ruined the victory by a haughty and ambitious pursuit made out of season.'},
  plut29ii:{ref:'Plutarco, Demetrio 29.3|Plutarch, Demetrius 29.3',lang:'grc',urn:PLU+'29',
    o:'αὐτὸς μὲν γὰρ οὐκ ἔσχε πάλιν ἀναστρέψας συμμῖξαι τοῖς πεζοῖς τῶν ἐλεφάντων ἐν μέσῳ γενομένων',
    tr:'Pues él mismo no pudo dar media vuelta y unirse de nuevo a la infantería, al haberse interpuesto los elefantes.|For he himself could not turn back and rejoin the infantry, since the elephants had come in between.'},
  plut29c:{ref:'Plutarco, Demetrio 29.4|Plutarch, Demetrius 29.4',lang:'grc',urn:PLU+'29',
    o:'τὴν δὲ φάλαγγα γυμνὴν ἱππέων κατιδόντες οἱ περι Σέλευκον οὐκ ἐνέβαλον μέν, ὡς δὲ ἐμβαλοῦντες ἐφόβουν καὶ περιήλαυνον, μεταβάλλεσθαι διδόντες αὐτοῖς· ὃ καὶ συνέβη. πολὺ γὰρ μέρος ἀπορραγὲν ἑκουσίως μετεχώρησε πρὸς ἐκείνους, τὸ δὲ λοιπὸν ἐτράπη.',
    tr:'Al ver la falange desnuda de caballería, los de Seleuco no cargaron, sino que, amagando la carga, la atemorizaban y cabalgaban a su alrededor, dándoles ocasión de cambiar de bando; y así ocurrió. Pues una gran parte se desgajó y se pasó voluntariamente a ellos, y el resto fue puesto en fuga.|Seeing the phalanx stripped of cavalry, Seleucus’ men did not charge, but, feinting a charge, frightened them and rode around them, giving them the chance to change sides; and so it happened. For a large part broke away and went over to them of its own accord, and the rest was routed.'},
  just172:{ref:'Justino 17.2.1|Justin 17.2.1',lang:'la',url:'https://www.thelatinlibrary.com/justin/17.html',
    o:'In eo bello Lysimachus amissis ante variis casibus quindecim liberis non instrenue moriens postremus domus suae ruinae cumulus accessit.',
    tr:'En aquella guerra Lisímaco, que antes había perdido por diversos azares a quince hijos, murió sin faltarle el brío y vino a ser el último remate de la ruina de su casa.|In that war Lysimachus, having earlier lost fifteen children by various mischances, died not without spirit and came as the final crown to the ruin of his house.'},
  luc8:{ref:'Luciano, Zeuxis 8|Lucian, Zeuxis 8',lang:'grc',urn:LUC+'8',
    o:'οἱ γυμνῆτες δὲ ὑπὲρ ἥμισυ τῆς στρατιᾶς ἦσαν. ὥστε ἐδόκει αὐτῷ ἤδη σπένδεσθαι καί τινα εὐπρεπῆ διάλυσιν εὑρίσκεσθαι τοῦ πολέμου.',
    tr:'Las tropas ligeras eran más de la mitad del ejército. De modo que ya le parecía cosa de pactar y buscar alguna salida decorosa de la guerra.|The light-armed made up more than half the army. So he was already minded to make a truce and find some decent way out of the war.'},
  luc10:{ref:'Luciano, Zeuxis 10|Lucian, Zeuxis 10',lang:'grc',urn:LUC+'10',
    o:'οὐ γὰρ πρότερον ἰδόντες ἐλέφαντα οὔτε αὐτοὶ Γαλάται οὔτε οἱ ἵπποι αὐτῶν οὕτω πρὸς τὸ παράδοξον τῆς ὄψεως ἐταράχθησαν, ὥστε […] πρὶν ἢ τὸ τόξευμα ἐξικνεῖσθαι, ἐκκλίναντες σὺν οὐδενὶ κόσμῳ ἔφευγον',
    tr:'Pues, como nunca antes habían visto un elefante ni los propios gálatas ni sus caballos, se turbaron tanto ante lo insólito de la visión que […], antes de estar a tiro de flecha, volvieron grupas y huyeron sin orden alguno.|For, never having seen an elephant before, neither the Galatians themselves nor their horses, they were so confounded by the strangeness of the sight that […], before they were within bowshot, they turned and fled in no order at all.'},
  luc10b:{ref:'Luciano, Zeuxis 10|Lucian, Zeuxis 10',lang:'grc',urn:LUC+'10',
    o:'εἵποντο δὲ καὶ οἱ ἐλέφαντες συμπατοῦντες καὶ συναναρριπτοῦντες ἐς ὕψος ταῖς προνομαίαις καὶ συναρπάζοντες καὶ τοῖς ὀδοῦσι περιπείροντες, καὶ τέλος οὗτοι κατὰ κράτος παραδιδόασι τῷ Αντιόχῳ τὴν νίκην.',
    tr:'Los seguían además los elefantes, pisoteando, lanzando por los aires con las trompas, arrebatando y ensartando con los colmillos; y al final son ellos quienes entregan a Antíoco una victoria aplastante.|The elephants followed too, trampling, tossing men aloft with their trunks, snatching them up and goring them with their tusks; and in the end it is they who hand Antiochus an overwhelming victory.'},
  just2710:{ref:'Justino 27.2.10|Justin 27.2.10',lang:'la',url:'https://www.thelatinlibrary.com/justin/27.html',
    o:'sed pax ab hoste data interpellatur a fratre, qui conducto Gallorum mercennario exercitu pro auxilio bellum, pro fratre hostem imploratus exhibuit.',
    tr:'Pero la paz concedida por el enemigo la rompe el hermano, que, tras contratar un ejército mercenario de galos, cuando se le pedía ayuda trajo la guerra y, en lugar de un hermano, se mostró un enemigo.|But the peace granted by the enemy is broken by the brother, who, having hired a mercenary army of Gauls, when asked for help brought war and, in place of a brother, showed himself an enemy.'},
  pol553b:{ref:'Polibio 5.53.6–7|Polybius 5.53.6–7',lang:'grc',urn:POL+'5.53.6-5.53.7',
    o:'Μόλων δὲ δύσχρηστον μὲν ἐποιήσατο τὴν ἐξαγωγήν, ταραχώδη δὲ καὶ τὴν ἔκταξιν διὰ τὴν ἐν τῇ νυκτὶ προγεγενημένην ἀλογίαν',
    tr:'Molón sacó sus tropas con dificultad, y también las formó en desorden, por el desconcierto que se había producido durante la noche.|Molon led out his troops with difficulty, and drew them up in confusion too, because of the disarray that had arisen during the night.'},
  pol5541:{ref:'Polibio 5.54.1–2|Polybius 5.54.1–2',lang:'grc',urn:POL+'5.54.1-5.54.2',
    o:'μετὰ δὲ ταῦτα ποιησαμένων τῶν δυνάμεων τὴν ἐπαγωγήν, τὸ μὲν δεξιὸν κέρας τοῦ Μόλωνος διετήρησε τὴν πίστιν καὶ συνέβαλε τοῖς περὶ τὸν Ζεῦξιν ἐρρωμένως, τὸ δʼ εὐώνυμον ἅμα τῷ συνιὸν εἰς ὄψιν ἐλθεῖν τῷ βασιλεῖ μετεβάλετο πρὸς τοὺς πολεμίους·',
    tr:'Después, cuando los ejércitos avanzaron al ataque, el ala derecha de Molón mantuvo la lealtad y chocó con vigor contra los de Zeuxis; pero la izquierda, en cuanto al avanzar quedó a la vista del rey, se pasó al enemigo.|After this, when the armies advanced to the attack, Molon’s right wing kept faith and engaged Zeuxis’ men vigorously, but the left, as soon as in advancing it came in sight of the king, went over to the enemy.'},
  pol5543:{ref:'Polibio 5.54.3|Polybius 5.54.3',lang:'grc',urn:POL+'5.54.3',
    o:'ὁ δὲ Μόλων συννοήσας τὸ γεγονὸς καὶ πανταχόθεν ἤδη κυκλούμενος, λαβὼν πρὸ ὀφθαλμῶν τὰς ἐσομένας περὶ αὑτὸν αἰκίας, ἐὰν ὑποχείριος γένηται καὶ ζωγρίᾳ ληφθῇ, προσήνεγκε τὰς χεῖρας ἑαυτῷ.',
    tr:'Molón, al comprender lo ocurrido y verse ya rodeado por todas partes, se puso ante los ojos los tormentos que le esperaban si caía en manos del rey y lo cogían vivo, y se quitó la vida.|Molon, realising what had happened and already surrounded on all sides, set before his eyes the torments that awaited him if he fell into the king’s hands and was taken alive, and laid hands on himself.'},
  pol582:{ref:'Polibio 5.82.7|Polybius 5.82.7',lang:'grc',urn:POL+'5.82.7',
    o:'τῶν δὲ θηρίων τὰ μὲν τετταράκοντα κατὰ τὸ λαιὸν ἦν, ἐφʼ οὗ Πτολεμαῖος αὐτὸς ἔμελλε ποιεῖσθαι τὸν κίνδυνον, τὰ δὲ τριάκοντα καὶ τρία πρὸ τοῦ δεξιοῦ κέρατος ἐτέτακτο κατʼ αὐτοὺς τοὺς μισθοφόρους ἱππεῖς.',
    tr:'De las fieras, cuarenta estaban en el ala izquierda, donde el propio Ptolomeo iba a combatir, y las otras treinta y tres se habían colocado delante del ala derecha, a la altura de la caballería mercenaria.|Of the beasts, forty were on the left, where Ptolemy himself was to fight, and the other thirty-three had been posted in front of the right wing, level with the mercenary cavalry.'},
  pol841:{ref:'Polibio 5.84.1–2|Polybius 5.84.1–2',lang:'grc',urn:POL+'5.84.1-5.84.2',
    o:'σημήναντες τὸ πολεμικὸν συνέβαλον πρῶτον τοῖς θηρίοις. ὀλίγα μὲν οὖν τινα τῶν παρὰ Πτολεμαίου συνήρεισε τοῖς ἐναντίοις· ἐφʼ ὧν ἐποίουν ἀγῶνα καλὸν οἱ πυργομαχοῦντες, ἐκ χειρὸς ταῖς σαρίσαις διαδορατιζόμενοι καὶ τύπτοντες ἀλλήλους',
    tr:'Dieron la señal de combate y chocaron primero con las fieras. Solo unas pocas de las de Ptolomeo se trabaron con las contrarias; sobre ellas, los que combatían desde las torres libraban una hermosa lucha, acometiéndose de cerca con las sarisas y golpeándose unos a otros.|They gave the signal for battle and engaged first with the beasts. Only a few of Ptolemy’s came to grips with their opponents; on these the men fighting from the towers made a fine fight of it, thrusting at close quarters with their sarissas and striking one another.'},
  pol847:{ref:'Polibio 5.84.7–8|Polybius 5.84.7–8',lang:'grc',urn:POL+'5.84.7-5.84.8',
    o:'τούτων δὲ διαταραχθέντων καὶ πρὸς τὰς αὑτῶν τάξεις συνωθουμένων, τὸ μὲν ἄγημα τὸ τοῦ Πτολεμαίου πιεζόμενον ὑπὸ τῶν θηρίων ἐνέκλινε, τοῖς δὲ περὶ τὸν Πολυκράτην καὶ τοῖς ὑπὸ τοῦτον ἱππεῦσι διατεταγμένοις οἱ περὶ τὸν Ἀντίοχον ὑπὲρ τὰ θηρία περικερῶντες καὶ προσπίπτοντες ἐνέβαλον.',
    tr:'Desbaratadas estas y empujadas contra sus propias filas, el agema de Ptolomeo cedió bajo la presión de las fieras, y los de Antíoco, rebasando el ala por fuera de los elefantes, cayeron sobre Polícrates y la caballería formada a sus órdenes y cargaron contra ellos.|When these had been thrown into confusion and driven back on their own lines, Ptolemy’s agema gave way under the pressure of the beasts, and Antiochus’ men, outflanking the wing beyond the elephants, fell upon Polycrates and the cavalry drawn up under him and charged them.'},
  pol853:{ref:'Polibio 5.85.3|Polybius 5.85.3',lang:'grc',urn:POL+'5.85.3',
    o:'αὐτὸς δʼ ἐξαγαγὼν κατὰ κέρας τοὺς ἱππεῖς καὶ τοὺς ὑπὸ τὰ θηρία τεταγμένους τῆς μὲν ἐφόδου τῶν θηρίων ἐκτὸς ἐγεγόνει, τοὺς δὲ τῶν πολεμίων ἱππεῖς, οὓς μὲν ὑπεραίρων, οἷς δὲ κατὰ κέρας ἐμβάλλων, ταχέως ἐτρέψατο.',
    tr:'Él mismo sacó por el ala a la caballería y a los que formaban detrás de las fieras, quedó fuera del alcance de la acometida de los elefantes y, rebasando a unos jinetes enemigos y cargando de flanco contra otros, pronto los puso en fuga.|He himself led out by the wing the cavalry and those posted behind the beasts, got clear of the elephants’ onset and, outflanking some of the enemy horsemen and charging others in flank, quickly routed them.'},
  pol858:{ref:'Polibio 5.85.8–9|Polybius 5.85.8–9',lang:'grc',urn:POL+'5.85.8-5.85.9',
    o:'Πτολεμαῖος δὲ τὴν ἀποχώρησιν ὑπὸ τὴν φάλαγγα πεποιημένος, τότε προελθὼν εἰς μέσον καὶ φανεὶς ταῖς δυνάμεσι τοὺς μὲν ὑπεναντίους κατεπλήξατο, τοῖς δὲ παρʼ αὑτοῦ μεγάλην ὁρμὴν ἐνειργάσατο καὶ προθυμίαν. διὸ καὶ καταβαλόντες παραχρῆμα τὰς σαρίσας οἱ περὶ τὸν Ἀνδρόμαχον καὶ Σωσίβιον ἐπῆγον.',
    tr:'Ptolomeo, que se había retirado al abrigo de la falange, se adelantó entonces hasta el centro y, al mostrarse a las tropas, sobrecogió a los contrarios e infundió en los suyos gran empuje y ardor. Por eso los de Andrómaco y Sosibio abatieron al punto las sarisas y avanzaron.|Ptolemy, who had withdrawn under cover of the phalanx, now came forward into the centre and, showing himself to the troops, struck dismay into the enemy and filled his own men with great spirit and eagerness. And so Andromachus’ and Sosibius’ men at once lowered their sarissas and advanced.'},
  pol8511:{ref:'Polibio 5.85.11|Polybius 5.85.11',lang:'grc',urn:POL+'5.85.11',
    o:'ὁ δʼ Ἀντίοχος, ὡς ἂν ἄπειρος καὶ νέος, ὑπολαμβάνων ἐκ τοῦ καθʼ ἑαυτὸν μέρους καὶ τὰ λοιπὰ παραπλησίως αὑτῷ πάντα νικᾶν, ἐπέκειτο τοῖς φεύγουσιν.',
    tr:'Antíoco, como joven e inexperto que era, suponiendo por lo que ocurría en su sector que también en todo lo demás vencían igual que él, seguía acosando a los que huían.|Antiochus, young and inexperienced as he was, supposing from his own part of the field that all the rest was winning in the same way, kept pressing on the fugitives.'},
  pol865:{ref:'Polibio 5.86.5|Polybius 5.86.5',lang:'grc',urn:POL+'5.86.5',
    o:'ἦσαν δʼ οἱ τετελευτηκότες τῶν παρʼ Ἀντιόχου πεζοὶ μὲν οὐ πολὺ λείποντες μυρίων, ἱππεῖς δὲ πλείους τριακοσίων· ζωγρίᾳ δʼ ἑάλωσαν ὑπὲρ τοὺς τετρακισχιλίους.',
    tr:'Los muertos del lado de Antíoco fueron poco menos de diez mil infantes y más de trescientos jinetes; y fueron hechos prisioneros más de cuatro mil.|The dead on Antiochus’ side were not much short of ten thousand foot and more than three hundred horse; and over four thousand were taken prisoner.'},
  pol1049c:{ref:'Polibio 10.49.6|Polybius 10.49.6',lang:'grc',urn:POL+'10.49.6',
    o:'οἱ δὲ τῶν Βακτριανῶν ἱππεῖς, σημηνάντων αὐτοῖς τῶν σκοπῶν τὸ γεγονός, ἐξεβοήθουν, καὶ κατὰ πορείαν συνέμισγον τοῖς ὑπεναντίοις.',
    tr:'Los jinetes bactrianos, cuando sus vigías les señalaron lo ocurrido, acudieron al rescate y, según iban en marcha, trababan combate con los contrarios.|The Bactrian horsemen, when their scouts signalled to them what had happened, rode out to the rescue and engaged their opponents while still on the march.'},
  pol1049d:{ref:'Polibio 10.49.11|Polybius 10.49.11',lang:'grc',urn:POL+'10.49.11',
    o:'κατὰ δὲ τὸν καιρὸν τοῦτον, τῶν πλείστων ἱππέων ἐκτεταγμένων ἤδη, Παναίτωλος ἐπαγαγεῖν παραγγείλας τὸν μὲν βασιλέα καὶ τοὺς μετʼ αὐτοῦ κινδυνεύοντας ἐδέξατο, τοὺς δὲ τῶν Βακτριανῶν ἐπιφερομένους ἀτάκτως ἐκ μεταβολῆς προτροπάδην ἠνάγκασε φυγεῖν.',
    tr:'En ese momento, cuando la mayor parte de la caballería estaba ya desplegada, Panétolo dio orden de avanzar, recogió al rey y a los que combatían con él y, a los bactrianos, que cargaban en desorden, los obligó a volver grupas y a huir a rienda suelta.|At this moment, most of the cavalry being now deployed, Panaetolus gave the order to advance, received the king and those fighting beside him and forced the Bactrians, who were charging in disorder, to wheel about and flee headlong.'},
  pol16191:{ref:'Polibio 16.19.1|Polybius 16.19.1',lang:'grc',urn:POL+'16.19.1',
    o:'μετὰ δὲ ταῦτά φησι καταπροτερουμένην τὴν φάλαγγα ταῖς εὐχειρίαις καὶ πιεζομένην ὑπὸ τῶν Αἰτωλῶν ἀναχωρεῖν ἐπὶ πόδα, τὰ δὲ θηρία τοὺς ἐγκλίνοντας ἐκδεχόμενα καὶ συμπίπτοντα τοῖς πολεμίοις μεγάλην παρέχεσθαι χρείαν.',
    tr:'Después dice que la falange, superada en destreza y apurada por los etolios, retrocedía paso a paso, y que las fieras, acogiendo a los que cedían y cayendo sobre los enemigos, prestaron un gran servicio.|After this he says that the phalanx, outdone in skill and hard pressed by the Aetolians, was retiring step by step, and that the beasts, receiving those who gave way and falling on the enemy, did great service.'},
  pol16196:{ref:'Polibio 16.19.6–7|Polybius 16.19.6–7',lang:'grc',urn:POL+'16.19.6-16.19.7',
    o:'ποῦ δʼ ὁ βασιλεὺς γέγονεν, ἢ τίνα παρέσχηται χρείαν ἐν τῇ μάχῃ, τὸ κάλλιστον σύστημα περὶ αὑτὸν ἐσχηκὼς καὶ τῶν πεζῶν καὶ τῶν ἱππέων; ἁπλῶς γὰρ οὐδὲν εἴρηται περὶ τούτων.',
    tr:'¿Y dónde estuvo el rey, o qué servicio prestó en la batalla, él que tenía a su lado el cuerpo más selecto de infantes y de jinetes? Sencillamente, no se dice nada de eso.|And where was the king, or what service did he render in the battle, he who had about him the finest body of both foot and horse? Simply nothing is said of this.'},
  pol161910:{ref:'Polibio 16.19.10–11|Polybius 16.19.10–11',lang:'grc',urn:POL+'16.19.10-16.19.11',
    o:'φησὶ γὰρ αὐτὸν ἰδόντα τοὺς περὶ τὸν νεώτερον Ἀντίοχον ἐκ τοῦ διώγματος ἐπιφαινομένους κατὰ νώτου τοῖς φαλαγγίταις, καὶ διὰ τοῦτο τὰς τοῦ νικᾶν ἐλπίδας ἀπογνόντα, ποιεῖσθαι τὴν ἀποχώρησιν· μετὰ δὲ ταῦτα συστῆναι τὸν μέγιστον κίνδυνον, κυκλωθείσης τῆς φάλαγγος ὑπό τε τῶν θηρίων καὶ τῶν ἱππέων, καὶ τελευταῖον ἀποχωρῆσαι τὸν Σκόπαν ἀπὸ τοῦ κινδύνου.',
    tr:'Pues dice que [Escopas], al ver a los de Antíoco el Joven aparecer, de vuelta de la persecución, a la espalda de los falangitas, dio por perdida la esperanza de vencer y emprendió la retirada; y que después de eso se libró el combate más duro, cuando la falange quedó rodeada por las fieras y la caballería, y que Escopas fue el último en retirarse del combate.|For he says that [Scopas], on seeing the younger Antiochus’ men appear, back from the pursuit, in the rear of the phalangites, gave up hope of victory and began his retreat; and that after this the hardest fighting took place, the phalanx being surrounded by the beasts and the cavalry, and that Scopas was the last to withdraw from the fight.'},
  liv36187:{ref:'Livio 36.18.7|Livy 36.18.7',lang:'la',urn:LIV+'36.18.7',
    o:'et ita modica altitudo valli erat, ut et locum superiorem suis ad pugnandum praeberet, et propter longitudinem hastarum subiectum haberet hostem.',
    tr:'Y la altura de la empalizada era la justa para dar a los suyos una posición más alta desde la que combatir y, por la longitud de las lanzas, tener al enemigo debajo y a su alcance.|And the height of the rampart was just enough to give his men a higher position to fight from and, because of the length of their spears, to keep the enemy beneath them and within reach.'},
  liv3619:{ref:'Livio 36.19.3|Livy 36.19.3',lang:'la',urn:LIV+'36.19.3',
    o:'ceterum, ut primum signaque et arma ex propinquo cognita errorem aperuerunt, tantus repente pavor omnis cepit, ut abiectis armis fugerent.',
    tr:'Pero, en cuanto las enseñas y las armas, reconocidas de cerca, deshicieron el error, se apoderó de todos un pánico tan repentino que arrojaron las armas y huyeron.|But as soon as the standards and arms, recognised at close range, revealed the mistake, such sudden panic seized them all that they threw away their arms and fled.'},
  liv3619b:{ref:'Livio 36.19.11|Livy 36.19.11',lang:'la',urn:LIV+'36.19.11',
    o:'nec praeter quingentos, qui circa regem fuerunt, ex toto exercitu quisquam effugit',
    tr:'y, fuera de los quinientos que iban en torno al rey, no escapó nadie de todo el ejército|and apart from the five hundred who were about the king, no one from the whole army escaped'},
  liv3741n:{ref:'Livio 37.41.3–4|Livy 37.41.3–4',lang:'la',urn:LIV+'37.41.3-37.41.4',
    o:'regii tam lata acie ne ex medio quidem cornua sua conspicere poterant, nedum extremi inter se conspicerentur, et umor arcus fundasque et iaculorum amenta emollierat.',
    tr:'Los del rey, con una línea tan ancha, no podían ver sus propias alas ni siquiera desde el centro, y menos aún verse unos a otros los de los extremos; y la humedad había ablandado los arcos, las hondas y las correas de las jabalinas.|The king’s men, with so broad a line, could not see their own wings even from the centre, still less could those at the extremes see one another; and the damp had softened the bows, the slings and the thongs of the javelins.'},
  liv3742a:{ref:'Livio 37.42.1–2|Livy 37.42.1–2',lang:'la',urn:LIV+'37.42.1-37.42.2',
    o:'auxilia enim subsidiaria, quae proxima locata erant, pavore et consternatione quadrigarum territa et ipsa in fugam versa nudarunt omnia usque ad cataphractos equites. ad quos cum dissipatis subsidiis pervenisset equitatus Romanus, ne primum quidem impetum sustinuerunt',
    tr:'Pues las tropas auxiliares de apoyo, que estaban colocadas al lado, aterradas por el pánico y el desconcierto de las cuadrigas, se dieron también a la fuga y dejaron todo al descubierto hasta los jinetes catafractos. Y cuando, dispersadas las reservas, la caballería romana llegó hasta estos, no aguantaron ni la primera acometida.|For the supporting auxiliaries, posted next to them, terrified by the panic and confusion of the chariots, themselves turned to flight and left everything exposed as far as the cataphract cavalry. And when, the reserves being scattered, the Roman cavalry reached these, they did not withstand even the first charge.'},
  liv3742b:{ref:'Livio 37.42.4–5|Livy 37.42.4–5',lang:'la',urn:LIV+'37.42.4-37.42.5',
    o:'ibi simul perturbati ordines et impeditus intercursu suorum usus praelongarum hastarum — sarisas Macedones vocant — intulere signa Romanae legiones et pila in perturbatos coniecere. ne interpositi quidem elephanti militem Romanum deterrebant',
    tr:'Allí, en cuanto se desordenaron las filas y los suyos, al meterse entre ellas, estorbaron el manejo de las larguísimas lanzas —los macedonios las llaman sarisas—, las legiones romanas avanzaron y arrojaron sus pila contra los desordenados. Ni siquiera los elefantes intercalados amedrentaban al soldado romano|There, as soon as the ranks were thrown into disorder and the use of the very long spears — the Macedonians call them sarissas — was hampered by their own men running in among them, the Roman legions advanced and hurled their pila at the disordered enemy. Not even the elephants placed in the intervals deterred the Roman soldier'},
  liv3742c:{ref:'Livio 37.42.7–8|Livy 37.42.7–8',lang:'la',urn:LIV+'37.42.7-37.42.8',
    o:'namque Antiochus a dextro cornu, cum ibi fiducia fluminis nulla subsidia cerneret praeter quattuor turmas equitum, et eas, dum applicant se suis, ripam nudantis, impetum in eam partem cum auxiliis et cataphracto equitatu fecit',
    tr:'Pues Antíoco, desde el ala derecha, al ver que allí, por la confianza en el río, no había más reservas que cuatro escuadrones de caballería, y que estos, al arrimarse a los suyos, dejaban la orilla al descubierto, cargó contra esa parte con las tropas auxiliares y la caballería catafracta|For Antiochus, on the right wing, seeing that there, through reliance on the river, there were no reserves except four troops of horse, and that these, in closing up to their own men, were leaving the bank bare, attacked that part with his auxiliaries and the cataphract cavalry'},
  liv3743:{ref:'Livio 37.43.6|Livy 37.43.6',lang:'la',urn:LIV+'37.43.6',
    o:'Antiochus postquam et eos, quorum terga modo viderat, repetentis pugnam et aliam et a castris et ex acie adfluentem turbam conspexit, in fugam vertit equum.',
    tr:'Antíoco, cuando vio que volvían al combate aquellos a quienes poco antes había visto la espalda, y que afluía otra multitud desde el campamento y desde la línea, volvió su caballo para huir.|Antiochus, when he saw those whose backs he had just seen returning to the fight, and another crowd streaming in both from the camp and from the line, turned his horse to flight.'},
  liv3744:{ref:'Livio 37.44.1–2|Livy 37.44.1–2',lang:'la',urn:LIV+'37.44.1-37.44.2',
    o:'ad quinquaginta milia peditum caesa eo die dicuntur, equitum tria milia; mille et quadringenti capti et quindecim cum rectoribus elephanti. Romanorum aliquot vulnerati sunt; ceciderunt non plus trecenti pedites, quattuor et viginti equites et de Eumenis exercitu quinque et viginti.',
    tr:'Se dice que aquel día murieron unos cincuenta mil infantes y tres mil jinetes; fueron capturados mil cuatrocientos hombres y quince elefantes con sus conductores. De los romanos hubo algunos heridos; no cayeron más de trescientos infantes, veinticuatro jinetes y, del ejército de Eumenes, veinticinco.|Some fifty thousand foot are said to have been killed that day, and three thousand horse; fourteen hundred men were captured, and fifteen elephants with their drivers. Of the Romans some were wounded; no more than three hundred foot fell, twenty-four horsemen and, from Eumenes’ army, twenty-five.'},
  mac640:{ref:'1 Macabeos 6.40|1 Maccabees 6.40',lang:'grc',urn:MAC+'6.40',
    o:'καὶ ἐξετάθη μέρος τι τῆς παρεμβολῆς τοῦ βασιλέως ἐπὶ τὰ ὑψηλὰ ὄρη, καί τινες ἐπὶ τὰ ταπεινά· καὶ ἤρχοντο ἀσφαλῶς καὶ τεταγμένως.',
    tr:'Y una parte del ejército del rey se extendió por los montes altos, y otros por las tierras bajas; y avanzaban con seguridad y en orden.|And part of the king’s army was spread out over the high hills, and some on the low ground; and they came on steadily and in good order.'},
  mac642:{ref:'1 Macabeos 6.42|1 Maccabees 6.42',lang:'grc',urn:MAC+'6.42',
    o:'καὶ ἤγγισεν Ἰούδας καὶ ἡ παρεμβολὴ αὐτοῦ εἰς παράταξιν, καὶ ἔπεσαν ἀπὸ τῆς παρεμβολῆς τοῦ βασιλέως ἑξακόσιοι ἄνδρες.',
    tr:'Y Judas y su ejército se acercaron para el combate, y cayeron del ejército del rey seiscientos hombres.|And Judas and his army drew near for battle, and six hundred men of the king’s army fell.'},
  mac647:{ref:'1 Macabeos 6.47|1 Maccabees 6.47',lang:'grc',urn:MAC+'6.47',
    o:'καὶ εἶδον τὴν ἰσχὺν τῆς βασιλείας καὶ τὰ ὁρμήματα τῶν δυνάμεων, καὶ ἐξέκλιναν ἀπʼ αὐτῶν.',
    tr:'Y vieron la fuerza del reino y el ímpetu de sus tropas, y se apartaron de ellos.|And they saw the strength of the kingdom and the fierce onset of its forces, and they turned away from them.'},
  mac96:{ref:'1 Macabeos 9.6|1 Maccabees 9.6',lang:'grc',urn:MAC+'9.6',
    o:'καὶ ἴδον τὸ πλῆθος τῶν δυνάμεων, ὅτι πολλοί εἰσιν, καὶ ἐφοβήθησαν σφόδρα· καὶ ἐξερύησαν πολλοὶ ἀπὸ τῆς παρεμβολῆς, οὐ κατελείφθησαν ἐξ αὐτῶν ἀλλ᾿ ἢ ὀκτακόσιοι ἄνδρες.',
    tr:'Y vieron la multitud de las tropas, que eran muchos, y tuvieron mucho miedo; y muchos se escabulleron del campamento: no quedaron de ellos más que ochocientos hombres.|And they saw the multitude of the forces, that they were many, and they were greatly afraid; and many slipped away from the camp: no more than eight hundred men of them were left.'},
  mac911:{ref:'1 Macabeos 9.11|1 Maccabees 9.11',lang:'grc',urn:MAC+'9.11',
    o:'καὶ ἐμερίσθη ἡ ἵππος εἰς δύο μέρη, καὶ οἱ σφενδονῆται καὶ οἱ τοξόται προεπορεύοντο τῆς δυνάμεως',
    tr:'y la caballería se dividió en dos cuerpos, y los honderos y los arqueros iban delante del ejército|and the cavalry was divided into two parts, and the slingers and the archers went before the army'},
  mac918:{ref:'1 Macabeos 9.18|1 Maccabees 9.18',lang:'grc',urn:MAC+'9.18',
    o:'καὶ Ἰούδας ἔπεσεν καὶ οἱ λοιποὶ ἔφυγον.',
    tr:'Y Judas cayó, y los demás huyeron.|And Judas fell, and the rest fled.'}
};
for(const k in CITAS){const c=CITAS[k];if(!c.url&&c.urn)c.url=SCA(c.urn);}

const GUIONES={
/* ---------- Gaza, 312 ---------- */
gaza:{fases:[
 {t:'El despliegue|The deployment',f:'f',src:'diod82',
  c:'Demetrio, que apenas pasa de los veinte años, quiere decidir la batalla con su ala izquierda: allí reúne lo mejor de su caballería y treinta de sus cuarenta y tres elefantes, y deja el ala derecha, la de Andrónico, retrasada y con orden de no empeñarse. Ptolomeo y Seleuco lo saben por sus exploradores y pasan sus tres mil mejores jinetes a su propia derecha, enfrente de él, con la empalizada y los tiradores delante.|Demetrius, barely past twenty, means to decide the battle with his left wing: there he masses the best of his cavalry and thirty of his forty-three elephants, leaving his right, under Andronicus, held back with orders not to engage. Ptolemy and Seleucus learn this from their scouts and move their three thousand best horsemen to their own right, opposite him, with the palisade and the skirmishers in front.',acc:[]},
 {t:'Combate de caballería en el extremo del ala|Cavalry fight at the tip of the wing',f:'f',src:'diod83b',
  c:'El ejército de Ptolomeo avanza con gran griterío. En la punta del ala chocan primero las vanguardias de caballería, y los de Demetrio llevan la mejor parte. Entonces Ptolomeo y Seleuco rodean el ala y cargan en columna: se rompen casi todas las lanzas y se sigue a espada, con los generales combatiendo delante de los suyos.|Ptolemy’s army advances with loud shouting. At the tip of the wing the cavalry advance guards clash first, and Demetrius’ men have the better of it. Then Ptolemy and Seleucus ride around the wing and charge in column: most of the lances are shattered and the fight goes on with swords, the generals fighting in front of their men.',
  acc:[['mv',['A5',7,6],['A6',8,6],['A7',6,6],['A8',9,6],['A9',5,6]],
       ['mv',['A2',14,6],['B2',14,5]],['at','B2','A2',2,{c:1}],
       ['mv',['A1',15,5],['A0',15,6]],['at','A1','B2',3,{c:2,st:3,cine:1}],
       ['mv',['B0',13,5],['B1',13,4]],['at','B0','A2',3,{c:2}]]},
 {t:'Los elefantes llegan a la empalizada|The elephants reach the palisade',f:'f',src:'diod84a',
  c:'Con la caballería igualada, los conductores indios lanzan a los elefantes. Avanzan hasta la empalizada de hierro y cadenas y allí quedan detenidos, acribillados por los lanzadores de jabalina y los arqueros; algunos se clavan en las puntas. Muertos casi todos los conductores, las fieras son capturadas.|With the cavalry evenly matched, the Indian drivers launch the elephants. They advance as far as the palisade of iron and chains and there they are halted, riddled by javelin-men and archers; some impale themselves on the spikes. With nearly all the drivers dead, the beasts are captured.',
  acc:[['mv',['B4',12,5],['B3',11,5]],['at','A4','B4',3],['at','B4','A3',1,{c:3}],
       ['at','A4','B3',3],['at','A3','B3',3,{cine:1}],['out','B4','captured'],['out','B3','captured']]},
 {t:'La caballería de Demetrio se desbanda|Demetrius’ cavalry breaks',f:'f',src:'diod84b',
  c:'La pérdida de los elefantes hunde el ánimo de la caballería antigónida, que vuelve grupas. Demetrio se queda casi solo, rogando a los suyos que aguanten, y tiene que irse con ellos.|The loss of the elephants breaks the spirit of the Antigonid cavalry, which turns about. Demetrius is left almost alone, begging his men to stand, and has to go with them.',
  acc:[['out','B2','fled'],['out','B1','fled'],['mv',['B0',13,1]],['out','B0','withdraw']]},
 {t:'Desenlace|Aftermath',f:'f',src:null,
  c:'Demetrio se retiró en buen orden hasta Gaza y siguió de noche hasta Azoto. Diodoro (19.85) cuenta más de quinientos muertos, la mayoría jinetes distinguidos, y más de ocho mil prisioneros: buena parte de la infantería, que apenas había combatido, se entregó. Ptolomeo devolvió sin rescate el bagaje real y a los cortesanos cautivos. Poco después Seleuco partía hacia Babilonia con un puñado de hombres.|Demetrius withdrew in good order to Gaza and went on by night to Azotus. Diodorus (19.85) counts more than five hundred dead, most of them distinguished horsemen, and over eight thousand prisoners: much of the infantry, which had hardly fought, surrendered. Ptolemy sent back the royal baggage and the captured courtiers without ransom. Soon afterwards Seleucus set out for Babylon with a handful of men.',
  acc:[['out','B6','captured'],['out','B7','captured'],['out','B8','captured'],['out','B9','fled'],['out','B10','fled'],['out','B5','fled'],['out','B11','withdraw']]}
]},

/* ---------- Seleuco contra Nicanor, 311 ---------- */
nicanor:{fases:[
 {t:'Oculto en los pantanos|Hidden in the marshes',f:'f',src:'diod92a',
  c:'Nicanor baja de Media con más de diez mil infantes y unos siete mil jinetes. Seleuco tiene poco más de tres mil infantes y cuatrocientos jinetes: cruza el Tigris y esconde a sus hombres en los pantanos. Nicanor llega al río, no encuentra a nadie, cree que el enemigo ha huido lejos y acampa junto a una posta real.|Nicanor comes down from Media with more than ten thousand foot and some seven thousand horse. Seleucus has little over three thousand foot and four hundred horse: he crosses the Tigris and hides his men in the marshes. Nicanor reaches the river, finds no one, assumes the enemy has fled far off and camps by a royal post-station.',acc:[]},
 {t:'El ataque nocturno|The night attack',f:'f',src:'diod92',
  c:'De noche, con la guardia del campamento descuidada, Seleuco cae sobre él de improviso. Diodoro solo habla de «gran confusión y espanto»: los movimientos que ves son la forma de representarlo sobre el tablero.|By night, with the camp carelessly guarded, Seleucus falls on it without warning. Diodorus speaks only of “great confusion and panic”: the moves you see are a way of showing it on the board.',
  acc:[['mv',['A4',4,3],['A5',6,4],['A1',4,4],['A2',5,4],['A3',7,4],['A0',5,5],['A6',4,5]],
       ['at','A2','B10',4,{cine:1}],['out','B10','fled'],['at','A6','B7',2]]},
 {t:'Cae Evagro y las tropas cambian de bando|Evagrus falls and the troops change sides',f:'f',src:null,
  c:'Los persas son los que presentan combate, y en él cae su sátrapa Evagro con otros jefes. Entonces la mayoría de los soldados, entre el miedo y el descontento con Antígono, se pasa a Seleuco. Es la frase de Diodoro que acabas de leer.|It is the Persians who put up a fight, and in it their satrap Evagrus falls with other leaders. Then most of the soldiers, between fear and discontent with Antigonus, go over to Seleucus. This is the sentence of Diodorus you have just read.',
  acc:[['mv',['B1',6,3]],['at','A3','B1',4,{c:1}],['at','A2','B1',3],
       ['pasa','B6'],['pasa','B7'],['pasa','B8'],['pasa','B9'],['pasa','B11'],['pasa','B2']]},
 {t:'Nicanor huye por el desierto|Nicanor flees through the desert',f:'f',src:'diod92b',
  c:'Nicanor se queda con unos pocos y, temiendo que lo entreguen, escapa con sus amigos.|Nicanor is left with a few men and, fearing that he will be handed over, escapes with his friends.',
  acc:[['mv',['B0',14,0],['B3',14,1],['B5',15,1]],['out','B0','fled'],['out','B3','fled'],['out','B5','fled'],['out','B4','fled']]},
 {t:'Desenlace|Aftermath',f:'f',src:null,
  c:'Con un ejército ya considerable y tratando a todos con benevolencia, Seleuco se ganó sin dificultad Susiana, Media y las regiones vecinas, y escribió a Ptolomeo contando lo hecho. Diodoro (19.92.5) dice que tenía ya «porte de rey».|With an army now considerable and treating everyone kindly, Seleucus easily won over Susiana, Media and the neighbouring regions, and wrote to Ptolemy about what he had done. Diodorus (19.92.5) says he already had “the bearing of a king”.',acc:[]}
]},

/* ---------- Ipso, 301 ---------- */
ipsos:{fases:[
 {t:'Los dos ejércitos|The two armies',f:'f',src:'plut28',
  c:'Plutarco es casi la única narración de la batalla, y es breve. Antes de ella cuenta los malos presagios: Demetrio sueña que Alejandro se pasa al enemigo, y Antígono, al salir de la tienda, tropieza y cae de bruces. Ninguna fuente describe las líneas: el despliegue del tablero es una propuesta.|Plutarch is almost the only narrative of the battle, and a brief one. Before it he tells of the bad omens: Demetrius dreams that Alexander goes over to the enemy, and Antigonus, coming out of his tent, stumbles and falls on his face. No source describes the lines: the deployment on the board is a proposal.',acc:[]},
 {t:'Demetrio derrota a Antíoco|Demetrius defeats Antiochus',f:'f',src:'plut29i',
  c:'Demetrio carga con lo mejor de la caballería contra la de Antíoco, el hijo de Seleuco, la pone en fuga… y la persigue demasiado lejos.|Demetrius charges with the best of the cavalry against that of Antiochus, Seleucus’ son, routs it… and pursues too far.',
  acc:[['mv',['B1',2,5],['B2',3,5],['B3',1,5],['A1',2,6]],['at','B1','A1',4,{push:1,st:3,cine:1}],
       ['mv',['B2',3,6]],['at','B2','A1',4],['out','A1','fled'],['out','A2','fled'],
       ['mv',['B1',2,9],['B2',3,9],['B3',1,9]]]},
 {t:'Los elefantes cierran el regreso|The elephants block the way back',f:'f',src:'plut29ii',
  c:'Cuando Demetrio quiere volver, los elefantes de Seleuco se han interpuesto entre él y su infantería, y los caballos no los atraviesan. Plutarco no dice si fue una maniobra prevista; muchos historiadores modernos creen que sí.|When Demetrius tries to return, Seleucus’ elephants have come between him and his infantry, and the horses will not pass them. Plutarch does not say whether the manoeuvre was planned; many modern historians think it was.',
  acc:[['mv',['A9',4,7],['A10',4,5],['A11',4,3]],['mv',['B1',3,6]],['say','B1','sin paso|no way through']]},
 {t:'La falange, sin caballería|The phalanx without cavalry',f:'m',src:'plut29c',
  c:'Seleuco no carga contra la falange descubierta: la rodea amagando, para darle tiempo a cambiar de bando. Una gran parte se pasa a él y el resto huye. Qué cuerpos se pasaron no lo sabemos: los del tablero son un ejemplo.|Seleucus does not charge the exposed phalanx: he rides around it feinting, to give it time to change sides. A large part goes over to him and the rest flees. Which bodies went over we do not know: those on the board are an example.',
  acc:[['mv',['A0',10,4],['A3',12,4]],['pasa','B6'],['pasa','B7'],
       ['out','B4','fled'],['out','B5','fled'],['out','B9','fled'],['out','B10','fled'],['out','B11','fled'],['out','B8','fled']]},
 {t:'Muere Antígono|Antigonus dies',f:'f',src:'plut29b',
  c:'Muchos se lanzan contra Antígono. «¿Pues qué otro blanco tienen sino yo? Pero Demetrio llegará en mi ayuda», responde. Sigue buscando a su hijo con la mirada cuando cae bajo una lluvia de jabalinas.|Many rush at Antigonus. “Why, what other mark have they but me? But Demetrius will come to my aid,” he replies. He is still looking round for his son when he falls under a shower of javelins.',
  acc:[['mv',['A8',7,3],['A7',7,2]],['at','A8','B0',4],['at','A7','B0',3,{cine:1}],['at','A8','B0',3]]},
 {t:'Desenlace|Aftermath',f:'f',src:null,
  c:'Demetrio escapó a Éfeso con cinco mil infantes y cuatro mil jinetes (Plutarco, Demetrio 30). Los vencedores se repartieron el reino de Antígono «como un gran cuerpo» al que cada uno cortó su parte.|Demetrius escaped to Ephesus with five thousand foot and four thousand horse (Plutarch, Demetrius 30). The victors divided Antigonus’ kingdom “like a great carcass”, each cutting off his share.',
  acc:[['out','B1','withdraw'],['out','B2','withdraw'],['out','B3','withdraw']]}
]},

/* ---------- Corupedio, 281 ---------- */
corupedium:{fases:[
 {t:'Los dos últimos|The last two',f:'f',src:'just17',
  c:'De esta batalla no se conserva ningún relato: sabemos quiénes combatieron, dónde y quién murió, y casi nada más. Lo que sigue lo marca siempre como reconstrucción.|No account of this battle survives: we know who fought, where, and who died, and almost nothing else. What follows is always marked as reconstruction.',acc:[]},
 {t:'Dos líneas que no conocemos|Two lines we do not know',f:'r',src:null,
  c:'Los ejércitos de los Sucesores solían formar con la falange en el centro, la caballería en las alas y los elefantes delante. Así se han dispuesto aquí, y así chocan: es una suposición razonable, no un dato.|The armies of the Successors usually formed with the phalanx in the centre, the cavalry on the wings and the elephants in front. They have been set out so here, and so they clash: a reasonable guess, not a fact.',
  acc:[['mv',['A4',5,5],['A11',6,5],['A5',7,5],['A3',8,5],['A12',9,5],['A6',10,5],['A7',8,6]],
       ['mv',['B3',4,4],['B4',5,4],['B5',6,4],['B6',7,4],['B8',9,4],['B9',10,4]],
       ['at','A11','B5',3,{c:1}],['at','B6','A5',2,{c:2}],['at','A12','B8',3,{c:1}]]},
 {t:'Cae Lisímaco|Lysimachus falls',f:'m',src:'just172',
  c:'Lisímaco murió combatiendo. Memnón de Heraclea (FGrHist 434 F 5.7) precisa que lo alcanzó una jabalina, y que quien la arrojó fue Malacón, un heracleota que servía con Seleuco. Dónde y cómo ocurrió sobre el terreno, no lo dice.|Lysimachus died fighting. Memnon of Heraclea (FGrHist 434 F 5.7) specifies that he was struck by a javelin, and that the man who threw it was Malacon, a Heracleot serving with Seleucus. Where and how it happened on the field he does not say.',
  acc:[['mv',['B0',8,4]],['at','A3','B0',4,{cine:1}],['at','A12','B0',3],['at','A3','B0',4]]},
 {t:'Desenlace|Aftermath',f:'f',src:null,
  c:'Apiano (Siríaca 64) cuenta que el perro de Lisímaco guardó el cadáver hasta que lo encontraron. Seleuco, último superviviente de los compañeros de Alejandro, se vio dueño de casi todo su imperio; unos siete meses después, recién pasado a Europa, lo asesinó Ptolomeo Cerauno.|Appian (Syriaca 64) says that Lysimachus’ dog guarded the body until it was found. Seleucus, last survivor of Alexander’s companions, saw himself master of almost all his empire; some seven months later, having just crossed to Europe, he was murdered by Ptolemy Ceraunus.',acc:[]}
]},

/* ---------- Batalla de los Elefantes, c. 275 ---------- */
elephants:{fases:[
 {t:'Un ejército pequeño ante una multitud|A small army before a multitude',f:'u',src:'luc8',
  c:'Todo lo que sabemos de esta batalla lo cuenta Luciano de Samósata, cuatro siglos después, en un discurso sobre la novedad en el arte: es un relato literario, con cifras de adorno. Según él, Antíoco, con pocas tropas y casi todas ligeras, pensaba ya en negociar.|All we know of this battle is told by Lucian of Samosata, four centuries later, in a speech about novelty in art: it is a literary account, with ornamental figures. According to him Antiochus, with few troops and most of them light, was already thinking of negotiating.',acc:[]},
 {t:'El plan de Teodotas|Theodotas’ plan',f:'u',src:'luc9',
  c:'Teodotas de Rodas le aconseja esconder los dieciséis elefantes y soltarlos solo cuando la caballería y los carros enemigos estén ya lanzados.|Theodotas of Rhodes advises him to hide the sixteen elephants and release them only when the enemy cavalry and chariots are already committed.',acc:[]},
 {t:'Cargan la caballería y los carros|The cavalry and the chariots charge',f:'u',src:null,
  c:'A la señal de la trompeta, la caballería gálata carga por las alas y la falange se abre para dejar salir a los carros. Entonces aparecen los elefantes: cuatro contra cada ala y ocho contra los carros.|At the trumpet signal the Galatian cavalry charges on the wings and the phalanx opens to let the chariots out. Then the elephants appear: four against each wing and eight against the chariots.',
  acc:[['mv',['B1',2,5],['B2',3,5],['B9',12,5],['B10',13,5],['B11',7,4],['B12',9,4]],
       ['mv',['A1',3,6],['A9',13,6],['A10',7,5],['A11',9,5]]]},
 {t:'El pánico|The panic',f:'u',src:'luc10',
  c:'Ni los gálatas ni sus caballos han visto nunca un elefante. Antes de llegar a tiro de flecha, los caballos se desbocan: los jinetes arrollan a su propia infantería y los carros dan media vuelta y siegan con las hoces a los suyos.|Neither the Galatians nor their horses have ever seen an elephant. Before coming within bowshot the horses bolt: the riders trample their own infantry and the chariots wheel about and mow down their own men with the scythes.',
  acc:[['say',['B1','B2','B9','B10','B11','B12'],'¡pánico!|panic!'],['mv',['B11',7,3],['B12',9,3]],
       ['hit','B5',3],['hit','B7',3],['hit','B4',2],['hit','B8',2],['out','B11','fled'],['out','B12','fled'],
       ['hit','B3',3],['out','B1','fled'],['out','B2','fled'],['out','B9','fled'],['out','B10','fled']]},
 {t:'Los elefantes rematan la victoria|The elephants finish the victory',f:'u',src:'luc10b',
  c:'Los elefantes siguen a los que huyen, y son ellos quienes dan la victoria. Muchos gálatas mueren y otros caen prisioneros; unos pocos escapan a los montes.|The elephants follow the fugitives, and it is they who give the victory. Many Galatians are killed and others taken prisoner; a few escape to the hills.',
  acc:[['mv',['A10',7,3],['A11',9,3],['A1',4,4]],['at','A10','B5',5,{cine:1}],['at','A11','B7',5],['at','A1','B3',5],
       ['out','B3','fled'],['out','B5','fled'],['out','B7','fled'],['out','B4','fled'],['out','B8','fled'],['out','B6','fled'],['out','B0','fled']]},
 {t:'El trofeo|The trophy',f:'u',src:'luc11',
  c:'Los macedonios aclaman a Antíoco y lo coronan. Él, según cuenta Luciano, llora de vergüenza.|The Macedonians acclaim Antiochus and crown him. He, Lucian says, weeps for shame.',acc:[]}
]},

/* ---------- Ancira, c. 239 ---------- */
ancyra:{fases:[
 {t:'La guerra de los hermanos|The War of the Brothers',f:'f',src:'just2710',
  c:'Antíoco Hierax tiene catorce años, según Justino, cuando su hermano le pide ayuda y él aprovecha para disputarle el reino con un ejército de gálatas a sueldo. De la batalla no hay relato: solo conocemos el resultado.|Antiochus Hierax is fourteen, according to Justin, when his brother asks him for help and he seizes the chance to contest the kingdom with an army of hired Galatians. There is no account of the battle: we know only the result.',acc:[]},
 {t:'La acometida de los gálatas|The Galatian onset',f:'r',src:null,
  c:'Justino atribuye la victoria «al valor de los gálatas». Cómo se combatió es reconstrucción: aquí las bandas gálatas y la caballería cargan contra la línea de Seleuco.|Justin credits the victory “to the valour of the Galatians”. How it was fought is reconstruction: here the Galatian bands and the cavalry charge Seleucus’ line.',
  acc:[['mv',['B4',5,6],['B5',6,6],['B8',9,6],['B9',10,6],['B6',7,4],['B7',8,4],['B11',11,6],['B12',13,6]],
       ['at','B5','A4',4,{push:1,cine:1}],['at','B4','A3',5],['at','B9','A8',5],['at','B8','A7',3,{c:2}],
       ['at','B12','A10',4],['at','B11','A9',3,{c:2}]]},
 {t:'Seleuco, dado por muerto|Seleucus, believed dead',f:'m',src:null,
  c:'Seleuco II fue derrotado; el cronista Porfirio, que transmite Eusebio, habla de veinte mil muertos. El rey desapareció del campo y se le creyó caído. Plutarco (Sobre el amor fraterno 18) cuenta que Hierax, al saberlo, se quitó la púrpura y guardó luto, y que hizo sacrificios de gratitud cuando supo que su hermano vivía.|Seleucus II was defeated; the chronicler Porphyry, transmitted by Eusebius, speaks of twenty thousand dead. The king vanished from the field and was believed fallen. Plutarch (On Brotherly Love 18) says that Hierax, on hearing it, put off the purple and went into mourning, and offered sacrifices of thanksgiving when he learned that his brother was alive.',
  acc:[['out','A3','fled'],['out','A8','fled'],['out','A10','fled'],['out','A4','fled'],
       ['say','A0','se le cree muerto|believed dead'],['mv',['A0',8,9]],['out','A0','withdraw'],
       ['out','A1','fled'],['out','A2','fled'],['out','A5','fled'],['out','A6','fled'],['out','A7','fled'],['out','A9','fled'],['out','A11','fled']]},
 {t:'Los gálatas se vuelven contra Hierax|The Galatians turn on Hierax',f:'f',src:'just27',
  c:'Convencidos de que Seleuco ha muerto, los mercenarios quieren acabar también con Hierax para saquear Asia a sus anchas. El vencedor tiene que comprar su vida con oro.|Convinced that Seleucus is dead, the mercenaries want to finish off Hierax too, so as to plunder Asia at will. The victor has to buy his life with gold.',
  acc:[['mv',['B4',7,1],['B5',9,1],['B8',8,0],['B9',8,2]],['say','B0','se rescata con oro|ransoms himself with gold']]},
 {t:'Desenlace|Aftermath',f:'f',src:null,
  c:'Seleuco II renunció a Asia Menor al norte del Tauro. Quien acabó ganando la guerra de los hermanos fue Átalo I de Pérgamo, que derrotó a Hierax y a sus gálatas y tomó el título de rey.|Seleucus II gave up Asia Minor north of the Taurus. The one who won the War of the Brothers in the end was Attalus I of Pergamon, who defeated Hierax and his Galatians and took the title of king.',acc:[]}
]},

/* ---------- Apolonia, 220 ---------- */
apollonia:{fases:[
 {t:'La línea del rey|The king’s line',f:'f',src:'pol553',
  c:'Polibio describe el despliegue de Antíoco de derecha a izquierda. Añade que repartió las reservas de infantería y caballería entre las dos alas con orden de envolver al enemigo en cuanto chocaran, y que dio la izquierda a Hermias y Zeuxis.|Polybius describes Antiochus’ deployment from right to left. He adds that he divided the reserves of foot and horse between the two wings with orders to envelop the enemy as soon as they engaged, and gave the left to Hermeias and Zeuxis.',acc:[]},
 {t:'Molón forma en desorden|Molon forms up in disorder',f:'f',src:'pol553b',
  c:'La noche anterior Molón había intentado un ataque nocturno, pero diez de sus hombres desertaron al rey y tuvo que volverse; llegó al alba a un campamento alborotado (Polibio 5.52). Aun así forma: caballería en las dos alas, infantería pesada y gálatas en el centro, tiradores por fuera y los carros falcados delante.|The night before, Molon had attempted a night attack, but ten of his men deserted to the king and he had to turn back; he reached a camp in uproar at dawn (Polybius 5.52). Even so he forms up: cavalry on both wings, heavy infantry and Galatians in the centre, skirmishers on the outside and the scythed chariots in front.',acc:[]},
 {t:'Un ala combate; la otra se pasa al rey|One wing fights; the other goes over to the king',f:'f',src:'pol5541',
  c:'El ala derecha, la de Molón, choca con vigor contra Zeuxis. La izquierda, la de su hermano Neolao, queda frente al rey: en cuanto lo ve, cambia de bando.|The right wing, Molon’s own, engages Zeuxis vigorously. The left, under his brother Neolaus, faces the king: as soon as it sees him, it changes sides.',
  acc:[['mv',['B2',2,6],['B0',3,5],['A2',3,6]],['at','B2','A2',3,{c:2,st:3,cine:1}],
       ['mv',['A1',2,7]],['at','A1','B2',3,{c:2}],
       ['mv',['B9',12,5],['B10',13,5],['B11',14,4],['A0',12,7],['A10',13,6]],
       ['pasa','B9'],['pasa','B10'],['pasa','B11']]},
 {t:'Molón, rodeado|Molon surrounded',f:'m',src:'pol5543',
  c:'Los de Molón se desmoralizan y los del rey cobran doble ánimo. Rodeado ya por todas partes, Molón se quita la vida para no caer vivo en manos de Antíoco. El cerco se representa aquí con las reservas del rey y con los que acaban de pasarse.|Molon’s men lose heart and the king’s are doubly encouraged. Already surrounded on every side, Molon takes his own life so as not to fall alive into Antiochus’ hands. The encirclement is shown here with the king’s reserves and with those who have just changed sides.',
  acc:[['out','B3','fled'],['out','B8','fled'],['out','B12','fled'],['out','B13','fled'],
       ['mv',['A10',4,5],['B9',3,4],['B10',2,4],['A0',6,5]],['at','A1','B2',4],['out','B2','fled'],['out','B0','suicide'],
       ['out','B4','captured'],['out','B5','captured'],['out','B6','captured'],['out','B7','captured'],['out','B1','fled']]},
 {t:'Desenlace|Aftermath',f:'f',src:null,
  c:'Los demás cabecillas huyeron a sus casas y acabaron del mismo modo; Neolao mató a la madre y a los hijos de Molón y luego se mató. El rey mandó empalar el cadáver de Molón en el lugar más visible de Media, en la subida del Zagros, reprendió largamente a las tropas rebeldes y las perdonó (Polibio 5.54).|The other ringleaders fled to their homes and ended in the same way; Neolaus killed Molon’s mother and children and then himself. The king had Molon’s body impaled in the most conspicuous place in Media, at the ascent of the Zagros, rebuked the rebel troops at length and pardoned them (Polybius 5.54).',acc:[]}
]},

/* ---------- Rafia, 217 ---------- */
raphia:{fases:[
 {t:'Los reyes, frente a frente|The kings face to face',f:'f',src:'pol582',
  c:'Polibio detalla las dos líneas. Lo esencial: las falanges en el centro, una frente a otra, y cada rey en un ala, Ptolomeo en su izquierda y Antíoco en su derecha, de modo que quedan frente a frente, cada uno con sus elefantes delante. En el tablero, los cretenses y mercenarios se han simplificado.|Polybius details both lines. The essentials: the phalanxes in the centre, facing each other, and each king on a wing, Ptolemy on his left and Antiochus on his right, so that they face each other, each with his elephants in front. On the board the Cretans and mercenaries have been simplified.',acc:[]},
 {t:'Chocan los elefantes|The elephants clash',f:'f',src:'pol841',
  c:'Ptolomeo, que ha recorrido la línea con su hermana Arsínoe, llega a su ala izquierda; Antíoco, a su derecha con el escuadrón real. Dan la señal y los primeros en chocar son los elefantes. Unos pocos de los africanos aguantan, y sobre ellos combaten las dotaciones de las torres.|Ptolemy, who has ridden along the line with his sister Arsinoe, reaches his left wing; Antiochus, his right with the royal squadron. They give the signal and the first to clash are the elephants. A few of the African ones stand their ground, and on them the tower crews fight.',
  acc:[['mv',['B3',2,4],['B4',4,4],['A2',2,5],['A3',4,5]],['at','B3','A2',4,{push:1,cine:1}],['at','A3','B4',1,{c:3}]]},
 {t:'Los africanos rehúyen el combate|The Africans shrink from the fight',f:'f',src:'pol845',
  c:'La mayoría de los elefantes de Ptolomeo no soporta el olor ni el bramido de los indios y huye antes de llegar al choque, contra sus propias filas.|Most of Ptolemy’s elephants cannot bear the smell or the trumpeting of the Indian ones and flee before coming to grips, back on to their own ranks.',
  acc:[['say',['A2','A3'],'¡huyen!|they flee!'],['at','B4','A3',3,{push:1}],['hit','A4',2],['hit','A1',1],['out','A2','fled'],['out','A3','fled']]},
 {t:'Antíoco rebasa el ala y carga|Antiochus outflanks the wing and charges',f:'f',src:'pol847',
  c:'El agema cede, empujado por las fieras. Antíoco rodea a los elefantes por fuera y carga contra la caballería de Polícrates; a la vez, los mercenarios griegos, que en el tablero van con los cretenses, desalojan a los peltastas. Toda el ala izquierda de Ptolomeo cede, y el rey se retira al abrigo de la falange.|The agema gives way, pushed by the beasts. Antiochus rides round the elephants on the outside and charges Polycrates’ cavalry; at the same time the Greek mercenaries, who on the board go with the Cretans, drive out the peltasts. Ptolemy’s whole left wing gives way, and the king withdraws under cover of the phalanx.',
  acc:[['mv',['B4',4,6],['B3',2,5],['B1',2,6],['B2',1,6],['B0',1,5]],['at','B2','A14',4,{push:1,st:3,cine:1}],
       ['at','B1','A1',4,{push:1,st:3}],['at','B4','A4',3,{push:1}],['mv',['A0',7,8]],['mv',['B2',1,7],['B1',2,7],['B5',5,5]],
       ['at','B2','A14',4],['out','A14','fled'],['at','B1','A1',4],['out','A1','fled'],['at','B5','A4',3],['out','A4','fled'],
       ['mv',['B0',2,8],['B1',3,9],['B2',2,9]]]},
 {t:'Equécrates vence en la otra ala|Echecrates wins on the other wing',f:'f',src:'pol853',
  c:'En el ala derecha de Ptolomeo, Equécrates el tesalio espera a ver qué pasa en la otra. Cuando ve que el polvo viene hacia los suyos y que sus elefantes ni se atreven a acercarse a los indios, ordena a Fóxidas atacar de frente con los mercenarios griegos y él saca la caballería por fuera de las fieras. Fóxidas pone en fuga a árabes y medos.|On Ptolemy’s right wing, Echecrates the Thessalian waits to see what happens on the other. When he sees the dust coming towards his own side and his elephants not even daring to approach the Indian ones, he orders Phoxidas to attack frontally with the Greek mercenaries and leads the cavalry out beyond the beasts himself. Phoxidas routs the Arabs and the Medes.',
  acc:[['mv',['A12',13,3]],['at','A12','B12',5,{push:1,st:3,cine:1}],['out','B12','fled'],
       ['mv',['A8',9,3],['A9',10,3]],['at','A8','B9',5],['out','B9','fled'],['at','A9','B10',5],['out','B10','fled']]},
 {t:'Ptolomeo se muestra ante la falange|Ptolemy shows himself before the phalanx',f:'f',src:'pol858',
  c:'Las dos falanges siguen intactas en medio de la llanura, sin alas a ninguno de los lados. Entonces Ptolomeo sale de detrás de la suya y se deja ver. Sus falangitas bajan las sarisas y avanzan: la tropa escogida siria aguanta un momento y el resto cede enseguida.|The two phalanxes stand intact in the middle of the plain, with no wings on either side. Then Ptolemy comes out from behind his own and lets himself be seen. His phalangites lower their sarissas and advance: the picked Syrian troops hold for a moment and the rest quickly give way.',
  acc:[['mv',['A0',7,6]],['mv',['A5',6,3],['A6',7,3],['A7',8,3],['A13',5,3],['A0',7,4]],
       ['at','A6','B7',4,{push:1,cine:1}],['at','A7','B8',4,{push:1}],['at','A5','B6',2,{c:2}],['at','A13','B6',2,{c:1}],['at','A5','B6',4,{push:1}],
       ['out','B7','fled'],['out','B8','fled'],['out','B6','fled'],['out','B5','fled']]},
 {t:'Antíoco vuelve demasiado tarde|Antiochus returns too late',f:'f',src:'pol8511',
  c:'Antíoco sigue persiguiendo, convencido de que vence en todas partes, hasta que un oficial veterano le señala la polvareda que va de la falange hacia su propio campamento. Intenta volver con el escuadrón real, pero encuentra a todos los suyos huyendo y se retira a Rafia.|Antiochus goes on pursuing, convinced he is winning everywhere, until a veteran officer points out the cloud of dust moving from the phalanx towards his own camp. He tries to ride back with the royal squadron, but finds all his men in flight and retires to Raphia.',
  acc:[['mv',['B0',2,4],['B1',3,4],['B2',1,4]],['mv',['B0',2,0],['B1',3,0],['B2',4,0]],
       ['out','B0','withdraw'],['out','B1','withdraw'],['out','B2','withdraw'],['out','B3','withdraw'],['out','B4','withdraw'],['out','B11','withdraw']]},
 {t:'El balance|The reckoning',f:'f',src:'pol865',
  c:'Ptolomeo perdió unos mil quinientos infantes y setecientos jinetes; de sus elefantes murieron dieciséis y la mayoría de los demás fue capturada. Antíoco perdió cinco elefantes. Celesiria volvió a manos de Ptolomeo. Los veinte mil egipcios armados a la macedonia, dirá después Polibio (5.107), sacaron de la victoria el orgullo que alimentó las revueltas de las décadas siguientes.|Ptolemy lost about fifteen hundred foot and seven hundred horse; sixteen of his elephants were killed and most of the others captured. Antiochus lost five elephants. Coele-Syria returned to Ptolemy. The twenty thousand Egyptians armed in the Macedonian manner, Polybius says later (5.107), drew from the victory the pride that fed the revolts of the following decades.',acc:[]}
]},

/* ---------- Río Ario, 208 ---------- */
arius:{fases:[
 {t:'La marcha nocturna|The night march',f:'f',src:'pol1049a',
  c:'Antíoco sabe que los diez mil jinetes bactrianos vigilan el río de día y se retiran de noche. Deja atrás el grueso del ejército y, con la caballería, la infantería ligera y diez mil peltastas, llega al río antes del alba y pasa.|Antiochus knows that the ten thousand Bactrian horsemen watch the river by day and withdraw at night. He leaves the main army behind and, with the cavalry, the light infantry and ten thousand peltasts, reaches the river before dawn and crosses.',acc:[]},
 {t:'Vuelve la caballería bactriana|The Bactrian cavalry returns',f:'f',src:'pol1049c',
  c:'Avisados por sus vigías, los bactrianos acuden y atacan según llegan. El rey ordena a los demás que formen por compañías y escuadrones y sale él mismo, con los dos mil jinetes que suelen combatir a su lado, a recibir la primera carga. La primera hiparquía es vencida.|Warned by their scouts, the Bactrians ride up and attack as they arrive. The king orders the rest to form up by companies and squadrons and goes out himself, with the two thousand horsemen who usually fight beside him, to meet the first charge. The first hipparchy is beaten.',
  acc:[['mv',['B4',8,3]],['at','A0','B4',4,{c:2,cine:1}],['at','A1','B4',3,{c:1}],['at','A2','B4',3]]},
 {t:'Cargan la segunda y la tercera hiparquía|The second and third hipparchies charge',f:'f',src:'pol1049b',
  c:'Llegan la segunda y la tercera, y los del rey se ven apurados. A Antíoco le matan el caballo y un golpe en la boca le cuesta varios dientes.|The second and third arrive, and the king’s men are hard pressed. Antiochus has his horse killed under him and a blow to the mouth costs him several teeth.',
  acc:[['mv',['B6',9,3],['B5',8,3]],['at','B6','A2',4,{c:1,st:2}],['at','B5','A0',4,{c:1,st:2,cine:1}],
       ['say','A0','pierde el caballo|loses his horse'],['at','B5','A1',3,{c:1}]]},
 {t:'Panétolo|Panaetolus',f:'f',src:'pol1049d',
  c:'Con el resto de la caballería ya desplegado, Panétolo avanza, recoge al rey y obliga a huir a los bactrianos, que cargaban en desorden. No se detienen hasta reunirse con Eutidemo, después de perder a la mayoría.|With the rest of the cavalry now deployed, Panaetolus advances, takes in the king and forces the Bactrians, who were charging in disorder, to flee. They do not stop until they rejoin Euthydemus, having lost most of their number.',
  acc:[['mv',['A6',10,4]],['at','A6','B6',5,{push:1,st:3,cine:1}],['out','B6','fled'],['at','A2','B5',4],['out','B5','fled'],
       ['out','B3','fled'],['out','B7','fled'],['out','B2','fled'],['out','B8','fled'],['out','B1','fled'],['out','B9','fled'],['out','B0','withdraw']]},
 {t:'Desenlace|Aftermath',f:'f',src:null,
  c:'Los del rey acamparon junto al río. Eutidemo, asustado, se retiró a Zariaspa, en Bactriana, donde resistió un largo asedio antes de pactar: conservó el título de rey y entregó sus elefantes (Polibio 11.34).|The king’s men camped by the river. Euthydemus, alarmed, withdrew to Zariaspa in Bactria, where he withstood a long siege before coming to terms: he kept the title of king and handed over his elephants (Polybius 11.34).',acc:[]}
]},

/* ---------- Panio, 200 ---------- */
panium:{fases:[
 {t:'El relato de Zenón|Zeno’s account',f:'d',src:'pol1618',
  c:'De Panio solo tenemos lo que Polibio cita de Zenón de Rodas… para criticarlo. Lo que vas a ver es la versión de Zenón, con las objeciones de Polibio. Según Zenón, el hijo mayor del rey ocupó las alturas antes del alba; el resto cruzó el río y formó en el llano, con los elefantes, los tarentinos y los tiradores delante de la falange.|Of Panium we have only what Polybius quotes from Zeno of Rhodes… in order to criticise him. What you are about to see is Zeno’s version, with Polybius’ objections. According to Zeno, the king’s elder son occupied the heights before dawn; the rest crossed the river and formed up on the plain, with the elephants, the Tarentines and the skirmishers in front of the phalanx.',acc:[]},
 {t:'Los catafractos deshacen a la caballería etolia|The cataphracts break the Aetolian cavalry',f:'d',src:'pol1619',
  c:'Antíoco el Joven carga con los catafractos, pone en fuga a la caballería de Ptolomeo, hijo de Aéropo, y la persigue. Zenón lo hace cargar «desde la montaña» después de haberlo colocado en el llano: es la primera incoherencia que señala Polibio.|Antiochus the Younger charges with the cataphracts, routs the cavalry of Ptolemy son of Aeropus and pursues it. Zeno has him charge “from the hills” after placing him on the plain: this is the first inconsistency Polybius points out.',
  acc:[['mv',['B8',10,4],['B9',11,4],['B10',12,4],['A7',10,5],['A8',11,5]],['at','A7','B8',5,{push:1,st:2,cine:1}],['at','A8','B9',6],
       ['out','B9','fled'],['out','B8','fled'],['out','B10','fled'],['mv',['A7',10,0],['A8',11,0]]]},
 {t:'Chocan las falanges|The phalanxes clash',f:'d',src:'pol16191',
  c:'Según Zenón, las falanges chocan; la de Antíoco, superada por la agilidad de los etolios, retrocede paso a paso, y los elefantes acogen a los que ceden y caen sobre el enemigo. Polibio pregunta cómo pudieron chocar si delante estaban los elefantes, la caballería y los tiradores, y cómo distinguían los elefantes, detrás de la falange, al amigo del enemigo.|According to Zeno the phalanxes clash; Antiochus’, outdone by the nimbleness of the Aetolians, retires step by step, and the elephants receive those who give way and fall on the enemy. Polybius asks how they could clash with the elephants, cavalry and skirmishers in front, and how the elephants, behind the phalanx, told friend from foe.',
  acc:[['mv',['A9',5,6],['A11',9,6],['A12',10,6],['A10',4,6]],
       ['mv',['A4',6,5],['A5',7,5],['A6',8,5],['B2',4,4],['B3',5,4],['B4',6,4],['B5',7,4],['B6',8,4],['B12',9,4],['B11',4,3]],
       ['at','B5','A5',4,{push:1,cine:1}],['at','B6','A6',4,{push:1}],['at','A4','B4',2,{c:2}],
       ['mv',['B5',7,5],['B6',8,5]],['mv',['A9',6,6]],['at','A11','B6',4,{c:1}],['at','A9','B5',3,{c:1}]]},
 {t:'Los catafractos aparecen por la espalda|The cataphracts appear in the rear',f:'d',src:'pol161910',
  c:'Escopas ve volver de la persecución a los catafractos, a la espalda de su falange, y da la batalla por perdida. La falange queda rodeada por los elefantes y la caballería. Zenón dice a la vez que Escopas fue el primero en retirarse y el último: otra contradicción que anota Polibio.|Scopas sees the cataphracts returning from the pursuit, in the rear of his phalanx, and gives the battle up for lost. The phalanx is surrounded by the elephants and the cavalry. Zeno says both that Scopas was the first to withdraw and the last: another contradiction Polybius notes.',
  acc:[['mv',['A7',7,4],['A8',8,4]],['say','B0','da la batalla por perdida|gives the battle up for lost'],
       ['at','A7','B5',5,{st:3}],['at','A8','B6',5],['out','B5','fall'],['out','B6','fall'],['out','B4','captured'],
       ['out','B12','fled'],['out','B11','fled'],['out','B7','fled'],['out','B1','fled'],
       ['out','B2','withdraw'],['out','B3','withdraw'],['out','B0','withdraw']]},
 {t:'Lo que Polibio no se cree|What Polybius does not believe',f:'d',src:'pol16196',
  c:'¿Dónde estuvo el rey, con la mejor infantería y caballería a su lado? ¿Y el hijo mayor, enviado a las alturas? Zenón no lo dice; Polibio añade que le atribuye al rey dos hijos llamados Antíoco cuando en la campaña solo había uno. Por eso en el tablero ni el rey ni las tropas de las alturas se han movido: nadie cuenta qué hicieron.|Where was the king, with the best foot and horse about him? And the elder son, sent to the heights? Zeno does not say; Polybius adds that he gives the king two sons called Antiochus when only one was on the campaign. That is why on the board neither the king nor the troops on the heights have moved: no one tells what they did.',acc:[]},
 {t:'Desenlace|Aftermath',f:'f',src:null,
  c:'Escopas escapó con diez mil hombres a Sidón, donde Antíoco lo sitió hasta que el hambre lo obligó a capitular. Celesiria, Fenicia y Judea pasaron definitivamente a los seléucidas (Jerónimo, Comentario a Daniel 11.15–16; Josefo, Antigüedades judías 12.131–133).|Scopas escaped with ten thousand men to Sidon, where Antiochus besieged him until hunger forced him to capitulate. Coele-Syria, Phoenicia and Judaea passed to the Seleucids for good (Jerome, Commentary on Daniel 11.15–16; Josephus, Jewish Antiquities 12.131–133).',acc:[]}
]},

/* ---------- Termópilas, 191 ---------- */
thermopylae:{fases:[
 {t:'El paso, cerrado|The pass closed',f:'f',src:'liv3618',
  c:'El cónsul forma con el frente estrecho que permite el lugar. Livio describe la posición del rey: infantería ligera delante de la empalizada, los sarisóforos como un baluarte junto a las defensas, los tiradores en la ladera, y los elefantes y la caballería en el extremo que da al mar.|The consul forms with the narrow front the place allows. Livy describes the king’s position: light infantry in front of the rampart, the sarissa-bearers like a bulwark by the defences, the skirmishers on the slope, and the elephants and cavalry at the end towards the sea.',acc:[]},
 {t:'El asalto frontal|The frontal assault',f:'f',src:null,
  c:'Al principio los macedonios aguantan sin dificultad delante de la empalizada, ayudados por la lluvia de piedras, flechas y jabalinas que cae desde la ladera. Cuando la presión romana se hace insoportable, se repliegan en orden detrás de las defensas.|At first the Macedonians hold easily in front of the rampart, helped by the rain of stones, arrows and javelins from the slope. When the Roman pressure becomes unbearable, they fall back in order behind the defences.',
  acc:[['mv',['B8',8,4],['B9',8,5],['B5',7,4],['B6',7,5],['B4',7,3],['B3',6,4],['B7',6,3]],
       ['at','B8','A1',3,{c:1}],['at','A5','B9',3],['mv',['A1',11,4]]]},
 {t:'Un segundo muro de lanzas|A second rampart of spears',f:'f',src:'liv36187',
  c:'Desde lo alto de la empalizada, con las sarisas tendidas, forman casi otra empalizada. Muchos romanos que se acercan sin cautela mueren atravesados.|From the top of the rampart, with their sarissas levelled, they form almost another rampart. Many Romans who come up incautiously are run through.',
  acc:[['mv',['B5',9,4],['B6',9,5],['B4',9,3]],['at','B5','A3',1,{c:3,cine:1}],['at','B6','A4',1,{c:3}],['at','B4','A2',1,{c:2}]]},
 {t:'Catón en el Calídromo|Cato on Callidromon',f:'f',src:'liv3618b',
  c:'El asalto habría fracasado si Catón no hubiera sorprendido de noche a los etolios del Calídromo, dormidos en su mayoría. Lucio Valerio Flaco, enviado contra los fuertes de Tiquiunte y Roduncia, no tuvo la misma suerte. Catón aparece en la altura que domina el campamento real.|The assault would have failed had Cato not surprised the Aetolians on Callidromon by night, most of them asleep. Lucius Valerius Flaccus, sent against the forts of Tichius and Rhoduntia, had no such luck. Cato appears on the height overlooking the royal camp.',
  acc:[['mv',['B11',10,8]],['at','B11','A9',6,{cine:1}],['out','A9','fall'],['mv',['B11',11,7]],['at','B11','A10',5],['out','A10','fled'],
       ['say','B10','rechazado|repulsed'],['mv',['B11',12,6]]]},
 {t:'El pánico|The panic',f:'f',src:'liv3619',
  c:'Los del rey creen primero que son etolios que vienen a ayudar. Cuando reconocen las enseñas, tiran las armas y huyen. La persecución se frena en las defensas, en la estrechez del paso y, sobre todo, en los elefantes, que cierran la columna: los caballos romanos no se atreven a pasar junto a ellos.|The king’s men think at first that they are Aetolians coming to help. When they recognise the standards, they throw away their arms and flee. The pursuit is held up by the defences, by the narrowness of the pass and, above all, by the elephants closing the column: the Roman horses dare not pass them.',
  acc:[['out','A6','fled'],['out','A5','fled'],['out','A3','fled'],['out','A4','fled'],['out','A2','fled'],['out','A1','fled'],
       ['mv',['A8',15,3],['A0',15,4],['A7',14,3]],['out','A8','withdraw'],['out','A0','withdraw'],
       ['mv',['B1',13,4]],['say','B1','los caballos no pasan|the horses will not pass'],['out','A7','fall']]},
 {t:'Desenlace|Aftermath',f:'f',src:'liv3619b',
  c:'Antíoco no se detuvo hasta Elatea y de allí pasó a Calcis con quinientos hombres. Livio, siguiendo a Polibio, le da diez mil al empezar, y descarta las cifras fantásticas de Valerio Antias. Los romanos perdieron unos doscientos hombres. Plutarco (Catón el Mayor 14) añade que una pedrada en la boca le rompió al rey los dientes.|Antiochus did not stop until Elatea and from there crossed to Chalcis with five hundred men. Livy, following Polybius, gives him ten thousand at the start, and dismisses the fantastic figures of Valerius Antias. The Romans lost about two hundred men. Plutarch (Cato the Elder 14) adds that a stone in the mouth broke the king’s teeth.',acc:[]}
]},

/* ---------- Magnesia, 190 ---------- */
magnesia:{fases:[
 {t:'La línea de Antíoco|Antiochus’ line',f:'f',src:'liv40',
  c:'Livio describe con detalle la formación del rey: la falange en el centro, en diez secciones con elefantes entre ellas; a los lados, gálatas, catafractos y la caballería de la guardia; delante del ala izquierda, los carros falcados. El rey manda la derecha, junto al río; su hijo Seleuco y Antípatro, la izquierda.|Livy describes the king’s formation in detail: the phalanx in the centre, in ten sections with elephants between them; on the flanks, Galatians, cataphracts and the guard cavalry; in front of the left wing, the scythed chariots. The king commands the right, by the river; his son Seleucus and Antipater, the left.',acc:[]},
 {t:'Niebla y humedad|Mist and damp',f:'f',src:'liv3741n',
  c:'La niebla de la mañana perjudica más al rey que a los romanos: su línea es tan larga que no se ve de un extremo a otro, y la humedad estropea arcos y hondas, mientras que no afecta a las espadas ni a los pila.|The morning mist harms the king more than the Romans: his line is so long that one end cannot see the other, and the damp spoils bows and slings, while it does not affect swords or pila.',acc:[]},
 {t:'Eumenes espanta a los carros|Eumenes stampedes the chariots',f:'f',src:'liv41',
  c:'Eumenes sabe lo incierto que es ese tipo de arma si se asusta a los caballos. Manda salir, dispersos, a los cretenses, los honderos y los lanzadores de jabalina, con algunos jinetes. Los carros, desbocados, vuelven contra los suyos y salen del campo.|Eumenes knows how uncertain that kind of weapon is if the horses are frightened. He sends out, in loose order, the Cretans, the slingers and the javelin-men, with some horsemen. The chariots, out of control, turn against their own side and leave the field.',
  acc:[['mv',['A9',13,5],['A10',13,4]],['at','A9','B12',4],['at','A10','B12',3,{cine:1}],
       ['say','B12','¡pánico!|panic!'],['hit','B11',2],['hit','B13',2],['out','B12','fled']]},
 {t:'Cede el ala izquierda del rey|The king’s left wing gives way',f:'f',src:'liv3742a',
  c:'El pánico de los carros arrastra a las tropas auxiliares que estaban al lado y deja a los catafractos al descubierto. La caballería romana y pergamena cae sobre ellos: unos huyen y a otros los alcanza el enemigo, estorbados por el peso de las armaduras.|The panic of the chariots carries away the auxiliaries posted beside them and leaves the cataphracts exposed. The Roman and Pergamene cavalry falls on them: some flee and others are overtaken, hampered by the weight of their armour.',
  acc:[['out','B13','fled'],['mv',['A7',13,3],['A8',13,1]],['at','A7','B11',5,{st:3,cine:1}],['at','A8','B11',4],['out','B10','fled'],['out','B9','fled']]},
 {t:'Las legiones contra la falange|The legions against the phalanx',f:'f',src:'liv3742b',
  c:'El desorden llega hasta el centro. Los fugitivos se meten entre las filas y las sarisas ya no pueden manejarse; las legiones avanzan y arrojan los pila. Tampoco los elefantes detienen a unos soldados que aprendieron en África a esquivarlos y herirlos de costado. Apiano (Siríaca 35) cuenta que la falange formó en cuadro y que fueron sus propios elefantes, enloquecidos por los proyectiles, los que la rompieron.|The disorder reaches the centre. The fugitives push in among the ranks and the sarissas can no longer be handled; the legions advance and throw their pila. Nor do the elephants stop soldiers who learned in Africa to dodge them and wound them from the side. Appian (Syriaca 35) says that the phalanx formed a square and that it was its own elephants, maddened by missiles, that broke it.',
  acc:[['mv',['A1',7,3],['A2',9,3],['A4',10,3],['A5',8,3]],['at','A1','B4',3,{c:1,cine:1}],['at','A5','B5',3],
       ['at','A2','B7',4],['at','A4','B7',3],['say','B7','¡pánico!|panic!'],['hit','B6',2],['hit','B8',2],['out','B7','fled'],
       ['at','A1','B5',4],['hit','B4',2],['out','B5','fled'],
       ['mv',['A7',11,2]],['at','A7','B8',4,{st:2}],['at','A2','B6',4]]},
 {t:'Mientras tanto, Antíoco rompe el ala del río|Meanwhile, Antiochus breaks the wing by the river',f:'f',src:'liv3742c',
  c:'En el otro extremo, los romanos se habían fiado del río y apenas tenían allí cuatro escuadrones. Antíoco carga con los catafractos y los auxiliares, de frente y por el flanco de la orilla: primero huye la caballería y luego la infantería vecina, hasta el campamento.|At the other end the Romans had trusted to the river and had barely four troops of horse there. Antiochus charges with the cataphracts and auxiliaries, in front and on the river flank: first the cavalry flees and then the neighbouring infantry, as far as the camp.',
  acc:[['mv',['B1',2,6],['B2',4,6],['B0',3,5]],['at','B1','A6',5,{st:3,cine:1}],['out','A6','fled'],
       ['at','B2','A3',4,{push:1,st:3}],['mv',['B1',2,9],['B2',5,9],['B0',3,8]]]},
 {t:'Emilio, Átalo y la huida del rey|Aemilius, Attalus and the king’s flight',f:'f',src:'liv3743',
  c:'El tribuno Marco Emilio, que guarda el campamento con dos mil hombres, sale al encuentro de los fugitivos y los obliga a volver al combate, ordenando matar a los primeros que huyen. Átalo, hermano de Eumenes, acude desde la otra ala con doscientos jinetes. Antíoco ve que el campo se llena de enemigos y vuelve grupas.|The tribune Marcus Aemilius, in charge of the camp with two thousand men, goes out to meet the fugitives and forces them back into the fight, ordering the foremost runaways to be cut down. Attalus, Eumenes’ brother, rides over from the other wing with two hundred horse. Antiochus sees the field filling with enemies and turns about.',
  acc:[['at','A12','B2',3,{c:1}],['at','A3','B2',2,{c:1}],['mv',['A8',5,8]],['at','A8','B2',3,{st:3}],
       ['mv',['B0',3,0],['B1',2,0],['B2',4,0]],['out','B0','withdraw'],['out','B1','withdraw'],['out','B2','withdraw'],
       ['out','B3','fled'],['out','B4','fall'],['out','B6','fall'],['out','B8','fall']]},
 {t:'El balance|The reckoning',f:'f',src:'liv3744',
  c:'Las cifras de Livio para las bajas del rey son las de la tradición romana y hay que tomarlas con cautela. Antíoco llegó a Sardes hacia medianoche y siguió a Apamea. La paz que se firmó allí en 188 a. C. le quitó Asia Menor al norte del Tauro, los elefantes y la flota.|Livy’s figures for the king’s losses are those of the Roman tradition and should be treated with caution. Antiochus reached Sardis about midnight and went on to Apamea. The peace signed there in 188 BC took from him Asia Minor north of the Taurus, his elephants and his fleet.',acc:[]}
]},

/* ---------- Pelusio, 170–169 ---------- */
pelusium:{fases:[
 {t:'A las puertas de Egipto|At the gates of Egypt',f:'f',src:'mac117',
  c:'Ningún autor antiguo describe esta batalla. El Primer libro de los Macabeos la resume en una frase, y Porfirio (en Jerónimo, Comentario a Daniel 11.21–24) la sitúa entre Pelusio y el monte Casio. Los que mandaban el ejército de Ptolomeo VI eran los regentes Euleo y Leneo.|No ancient author describes this battle. The First Book of Maccabees sums it up in a sentence, and Porphyry (in Jerome, Commentary on Daniel 11.21–24) places it between Pelusium and Mount Casius. Those in command of Ptolemy VI’s army were the regents Eulaeus and Lenaeus.',acc:[]},
 {t:'Un combate que no conocemos|A fight we do not know',f:'r',src:null,
  c:'Lo que ves es solo verosímil: los elefantes indios y la caballería pesada de Antíoco, armas que el texto de los Macabeos menciona, abren el combate contra las alas y los elefantes africanos.|What you see is merely plausible: Antiochus’ Indian elephants and heavy cavalry, arms the text of Maccabees mentions, open the fight against the wings and the African elephants.',
  acc:[['mv',['A10',6,4],['A11',8,4],['A2',4,4],['A9',11,4],['A4',6,5],['A5',7,5],['A6',8,5]],
       ['at','A11','B11',4],['at','A10','B11',3],['say','B11','¡pánico!|panic!'],['hit','B5',2],['out','B11','fled'],
       ['at','A2','B2',5,{st:3,cine:1}],['out','B2','fled'],['at','A9','B8',5,{st:3}],['out','B8','fled']]},
 {t:'La clemencia de Antíoco|Antiochus’ clemency',f:'m',src:'diod3014',
  c:'El ejército ptolemaico fue derrotado y huyó. Diodoro solo conserva un detalle: Antíoco recorrió el campo a caballo para impedir la matanza de los vencidos.|The Ptolemaic army was defeated and fled. Diodorus preserves a single detail: Antiochus rode about the field to stop the slaughter of the beaten.',
  acc:[['mv',['A4',6,3],['A5',7,3],['A6',8,3]],['at','A5','B5',3,{c:1}],
       ['out','B0','fled'],['out','B1','fled'],['out','B9','fled'],['out','B10','fled'],['mv',['A0',7,5]],
       ['out','B4','captured'],['out','B5','captured'],['out','B6','captured'],['out','B3','captured'],['out','B7','captured']]},
 {t:'Desenlace|Aftermath',f:'f',src:null,
  c:'Antíoco tomó Pelusio y ocupó casi todo Egipto salvo Alejandría. En su segunda invasión, en 168 a. C., el legado romano Popilio Lenas le entregó en Eleusis el ultimátum del Senado y trazó a su alrededor un círculo en la arena del que no debía salir sin responder (Polibio 29.27). Antíoco se retiró.|Antiochus took Pelusium and occupied almost all Egypt except Alexandria. On his second invasion, in 168 BC, the Roman envoy Popilius Laenas handed him the Senate’s ultimatum at Eleusis and drew a circle round him in the sand which he was not to leave without answering (Polybius 29.27). Antiochus withdrew.',acc:[]}
]},

/* ---------- Bet Zacarías, 162 ---------- */
bethzechariah:{fases:[
 {t:'El ejército real|The royal army',f:'f',src:'mac639',
  c:'El relato es el del Primer libro de los Macabeos, escrito desde el lado judío una o dos generaciones después. Sus cifras (cien mil infantes, veinte mil jinetes, treinta y dos elefantes) son muy exageradas; Josefo, en la Guerra de los judíos (1.41), da otras: cincuenta mil infantes, cinco mil jinetes y ochenta elefantes. El texto cuenta que a los elefantes les mostraron zumo de uva y de moras para excitarlos, y que cada uno iba escoltado por mil infantes y quinientos jinetes.|The account is that of the First Book of Maccabees, written from the Jewish side a generation or two later. Its figures (a hundred thousand foot, twenty thousand horse, thirty-two elephants) are much exaggerated; Josephus, in the Jewish War (1.41), gives others: fifty thousand foot, five thousand horse and eighty elephants. The text says the elephants were shown the juice of grapes and mulberries to rouse them, and that each was escorted by a thousand foot and five hundred horse.',acc:[]},
 {t:'El avance|The advance',f:'f',src:'mac640',
  c:'Una parte del ejército avanza por las alturas y otra por el fondo del valle, con los elefantes repartidos entre las formaciones. «Todos temblaban al oír el estruendo de la multitud y el choque de las armas» (6.41).|Part of the army advances over the heights and part along the valley floor, with the elephants distributed among the formations. “All trembled who heard the noise of their multitude and the clash of arms” (6.41).',
  acc:[['mv',['A10',5,4],['A11',8,4],['A12',11,4],['A2',5,5],['A5',8,5],['A7',11,5],['A3',6,5],['A6',10,5],['A1',2,4],['A9',13,4],['A4',7,6],['A0',8,7],['A8',12,6]]]},
 {t:'Judas ataca|Judas attacks',f:'f',src:'mac642',
  c:'Judas se acerca y presenta combate. El texto no da más detalle que el número de caídos del rey.|Judas draws near and offers battle. The text gives no detail beyond the number of the king’s men who fell.',
  acc:[['mv',['B4',6,4],['B5',8,3],['B6',10,4]],['at','B4','A3',3,{c:2}],['at','B6','A6',3,{c:2}],['at','B3','A10',2]]},
 {t:'Eleazar y el elefante|Eleazar and the elephant',f:'f',src:'mac646',
  c:'Eleazar Avarán, hermano de Judas, ve un elefante con arreos reales, más alto que los demás, y cree que lleva al rey. Corre hacia él por en medio de la formación, matando a derecha e izquierda, se mete debajo y lo hiere de muerte. El animal se desploma sobre él. El rey, un niño de unos nueve años, no iba en el elefante.|Eleazar Avaran, Judas’ brother, sees an elephant in royal harness, taller than the rest, and thinks it carries the king. He runs at it through the midst of the formation, killing right and left, gets underneath and wounds it mortally. The animal collapses on top of him. The king, a boy of about nine, was not on the elephant.',
  acc:[['mv',['B8',7,4]],['at','B8','A11',6],['at','B8','A11',4,{cine:1}],['out','B8','fall']]},
 {t:'La retirada|The withdrawal',f:'f',src:'mac647',
  c:'Ni la hazaña de Eleazar cambia el resultado. Los judíos ven la fuerza del ejército real y se apartan. Josefo (Guerra de los judíos 1.45) dice que Judas se retiró a la toparquía de Gofna.|Not even Eleazar’s deed changes the outcome. The Jews see the strength of the royal army and turn away. Josephus (Jewish War 1.45) says that Judas withdrew to the toparchy of Gophna.',
  acc:[['mv',['B4',6,2],['B5',8,2],['B6',10,2]],
       ['out','B1','withdraw'],['out','B2','withdraw'],['out','B7','withdraw'],['out','B9','withdraw'],['out','B3','withdraw'],
       ['out','B4','withdraw'],['out','B5','withdraw'],['out','B6','withdraw'],['out','B0','withdraw']]},
 {t:'Desenlace|Aftermath',f:'f',src:null,
  c:'Lisias tomó Bet Sur y sitió el Templo. Pero Filipo, a quien Antíoco IV había confiado la regencia al morir, volvía de Persia con el ejército: Lisias ofreció la paz, permitió a los judíos vivir según sus leyes y regresó a Antioquía (1 Macabeos 6.55–63).|Lysias took Beth Zur and besieged the Temple. But Philip, to whom Antiochus IV had entrusted the regency on his deathbed, was returning from Persia with the army: Lysias offered peace, allowed the Jews to live by their own laws and went back to Antioch (1 Maccabees 6.55–63).',acc:[]}
]},

/* ---------- Elasa, 160 ---------- */
elasa:{fases:[
 {t:'Ochocientos|Eight hundred',f:'f',src:'mac96',
  c:'Báquides llega con veinte mil infantes y dos mil jinetes. Judas acampa en Elasa con tres mil hombres escogidos, pero al ver al enemigo casi todos se van.|Bacchides arrives with twenty thousand foot and two thousand horse. Judas camps at Elasa with three thousand picked men, but at the sight of the enemy nearly all leave.',acc:[]},
 {t:'«Muramos con valor»|“Let us die bravely”',f:'f',src:'mac910',
  c:'Los que quedan le piden que se retire y vuelva más tarde con sus hermanos. Judas se niega.|Those who remain beg him to withdraw and come back later with his brothers. Judas refuses.',acc:[]},
 {t:'Avanza el ejército de Báquides|Bacchides’ army advances',f:'f',src:'mac911',
  c:'La caballería se divide en dos cuerpos; honderos y arqueros van delante, con los más fuertes en primera línea. Báquides está en el ala derecha. La falange avanza por ambos lados al son de las trompetas y, dice el texto, se combate desde la mañana hasta la tarde.|The cavalry divides into two bodies; slingers and archers go in front, with the strongest men in the first line. Bacchides is on the right wing. The phalanx advances on both sides to the sound of trumpets and, the text says, they fight from morning till evening.',
  acc:[['mv',['A11',7,4],['A12',9,4],['A3',5,5],['A4',6,5],['A5',7,5],['A6',9,5],['A7',10,5],['A8',11,5],['A0',12,6],['A9',13,6],['A10',14,5],['A1',3,5],['A2',4,5]],
       ['at','A11','B1',2]]},
 {t:'Judas rompe el ala derecha|Judas breaks the right wing',f:'f',src:'mac915',
  c:'Judas ve que Báquides y lo más fuerte del ejército están a la derecha y va contra ellos con los más valientes. Deshace el ala y la persigue hasta el monte Azoto.|Judas sees that Bacchides and the strength of the army are on the right and goes against them with the bravest. He breaks the wing and pursues it as far as Mount Azotus.',
  acc:[['mv',['B0',11,4],['B1',10,4],['B2',12,4]],['at','B0','A8',5,{push:1,cine:1}],['at','B1','A7',4,{push:1}],
       ['out','A8','fled'],['out','A7','fled'],['out','A6','fled'],['out','A12','fled'],['out','A9','fled'],['out','A10','fled'],
       ['mv',['A0',12,8]],['mv',['B0',11,7],['B1',10,7],['B2',12,7]]]},
 {t:'El ala izquierda se revuelve|The left wing wheels round',f:'f',src:'mac918',
  c:'Los del ala izquierda ven deshecha la derecha y se vuelven tras los pasos de Judas, por la espalda. El combate se endurece y caen muchos de los dos bandos.|Those on the left wing see the right broken and turn to follow on Judas’ heels, from behind. The fighting grows heavy and many fall on both sides.',
  acc:[['mv',['A5',11,6],['A4',10,6],['A3',9,6],['A1',12,6],['A2',13,6]],
       ['at','A5','B0',4,{c:2,cine:1}],['at','A4','B1',4,{c:2}],['at','A1','B2',5,{st:3}],['at','A5','B0',4],['at','A0','B0',3],
       ['out','B1','fled'],['out','B2','fled'],['out','B3','fled'],['out','B4','fled'],['out','B5','fled']]},
 {t:'Desenlace|Aftermath',f:'f',src:null,
  c:'Jonatán y Simón recogieron el cuerpo de su hermano y lo enterraron en la tumba de sus padres, en Modín. «¡Cómo ha caído el héroe que salvaba a Israel!», dice el lamento del texto (1 Macabeos 9.21). Jonatán tomó el mando.|Jonathan and Simon took up their brother’s body and buried it in the tomb of their fathers at Modein. “How is the mighty fallen, the saviour of Israel!” runs the lament in the text (1 Maccabees 9.21). Jonathan took command.',acc:[]}
]},

/* ---------- Enóparas, 145 ---------- */
oenoparas:{fases:[
 {t:'Suegro contra yerno|Father-in-law against son-in-law',f:'f',src:null,
  c:'De la batalla solo se conservan dos noticias: que Ptolomeo VI y Demetrio II vencieron, y el accidente del rey de Egipto. Estrabón (16.2.8) da el lugar: el río Enóparas, en la llanura de Antioquía. El desarrollo del combate es reconstrucción.|Only two reports of the battle survive: that Ptolemy VI and Demetrius II won, and the accident to the king of Egypt. Strabo (16.2.8) gives the place: the river Oenoparas, on the plain of Antioch. The course of the fighting is reconstruction.',acc:[]},
 {t:'Las líneas chocan|The lines clash',f:'r',src:null,
  c:'Las falanges avanzan una contra otra con los elefantes delante, como era habitual. No hay fuente para estos movimientos.|The phalanxes advance against each other with the elephants in front, as was usual. There is no source for these moves.',
  acc:[['mv',['B5',5,4],['B6',7,4],['B7',8,4],['B8',9,4],['B10',6,5],['A4',5,5],['A5',7,5],['A6',8,5],['A7',9,5]],
       ['at','B10','A10',3,{c:2}],['at','A5','B6',2,{c:2}]]},
 {t:'El caballo de Ptolomeo|Ptolemy’s horse',f:'m',src:'jos13117',
  c:'En pleno combate, el caballo de Ptolomeo se espanta al oír bramar a un elefante y lo derriba. Los enemigos se lanzan sobre él y lo hieren gravemente en la cabeza antes de que su guardia logre sacarlo.|In the thick of the fight Ptolemy’s horse takes fright at the trumpeting of an elephant and throws him. The enemy rush at him and wound him severely in the head before his guards manage to carry him off.',
  acc:[['mv',['A0',6,6]],['say','A0','el caballo se espanta|the horse bolts'],['mv',['B2',5,6]],['at','B2','A0',6,{st:3,cine:1}],
       ['mv',['A2',4,6]],['mv',['A0',6,9]],['at','A2','B2',4,{push:1}]]},
 {t:'Balas, vencido|Balas beaten',f:'m',src:'mac1115',
  c:'Pese a la caída del rey, su ejército vence. Alejandro Balas huye a Arabia.|Despite the king’s fall, his army wins. Alexander Balas flees to Arabia.',
  acc:[['at','A5','B6',4,{push:1}],['at','A6','B7',4,{push:1}],['mv',['A9',10,3]],['at','A9','B9',5,{st:3,cine:1}],['out','B9','fled'],
       ['mv',['B0',7,0]],['out','B0','fled'],
       ['out','B1','fled'],['out','B2','fled'],['out','B3','fled'],['out','B4','fled'],['out','B5','fled'],['out','B6','fled'],['out','B7','fled'],['out','B8','fled'],['out','B10','fled'],['out','B11','fled']]},
 {t:'Desenlace|Aftermath',f:'f',src:null,
  c:'Ptolomeo estuvo cuatro días sin conocimiento. Al quinto, cuenta Josefo, volvió en sí a tiempo de ver la cabeza de Balas, que le enviaba el jefe árabe Zabdiel, y murió poco después. Demetrio II, único rey, se deshizo enseguida de las guarniciones egipcias.|Ptolemy lay four days unconscious. On the fifth, Josephus says, he came to himself in time to see the head of Balas, sent to him by the Arab chief Zabdiel, and died soon afterwards. Demetrius II, sole king, at once got rid of the Egyptian garrisons.',acc:[]}
]},

/* ---------- Antíoco VII en Media, 129 ---------- */
media:{fases:[
 {t:'Los cuarteles de invierno|Winter quarters',f:'f',src:'just3810',
  c:'Antíoco VII había repartido su ejército por las ciudades de Media. Hartas de alojarlo, se sublevaron todas el mismo día, de acuerdo con Fraates. El rey salió a socorrer al destacamento más próximo con las tropas que tenía consigo y se encontró de frente con el ejército parto. No hay relato del combate: solo dos resúmenes.|Antiochus VII had spread his army through the cities of Media. Tired of billeting it, they all rose on the same day, in concert with Phraates. The king set out to relieve the nearest detachment with the troops he had with him and ran straight into the Parthian army. There is no account of the fighting: only two summaries.',acc:[]},
 {t:'El rey decide combatir|The king decides to fight',f:'m',src:'diod3416',
  c:'Sus amigos le aconsejan no trabar combate con un enemigo muy superior en número y retirarse a las montañas cercanas. Antíoco no les hace caso y aguanta la primera acometida. La lluvia de flechas de los arqueros a caballo es reconstrucción: era la forma de combatir de los partos.|His friends advise him not to engage an enemy far superior in numbers and to fall back to the nearby hills. Antiochus pays no heed and withstands the first onset. The hail of arrows from the horse archers is reconstruction: it was the Parthian way of fighting.',
  acc:[['mv',['B4',5,5],['B3',4,5],['B8',11,4],['B9',12,5]],['at','B4','A3',2],['at','B3','A2',2],['at','B8','A7',2],['at','B9','A9',2]]},
 {t:'Ateneo es el primero en huir|Athenaeus is the first to flee',f:'f',src:null,
  c:'Ateneo, el general que había cometido los abusos en los alojamientos, es el primero en abandonar el campo, y las tropas lo siguen. Lo cuenta Diodoro, en el fragmento que acabas de leer.|Athenaeus, the general who had committed the abuses in the billets, is the first to leave the field, and the troops follow him. Diodorus tells this, in the fragment you have just read.',
  acc:[['out','A1','fled'],['out','A2','fled'],['out','A3','fled'],['out','A7','fled'],['out','A10','fled'],['out','A9','fled']]},
 {t:'El rey combate casi solo|The king fights almost alone',f:'m',src:null,
  c:'Justino dice que Antíoco combatió con más valor que su ejército y que, abandonado por los suyos, fue muerto. Otras tradiciones difieren: según Apiano (Siríaca 68), se quitó la vida tras la derrota.|Justin says that Antiochus fought more bravely than his army and that, deserted by his men, he was killed. Other traditions differ: according to Appian (Syriaca 68), he took his own life after the defeat.',
  acc:[['mv',['B5',7,5],['B7',9,5]],['at','B5','A4',4,{c:2,st:3}],['at','B7','A6',3,{c:3,st:3}],['mv',['A0',8,5]],
       ['at','A0','B5',4,{c:2,cine:1}],['at','B7','A0',4],['at','B5','A0',4],
       ['out','A4','fled'],['out','A5','fled'],['out','A6','fled'],['out','A8','fled']]},
 {t:'Desenlace|Aftermath',f:'f',src:null,
  c:'Fraates le hizo funerales de rey y se casó con una hija de Demetrio II que Antíoco llevaba consigo (Justino 38.10.10). Fue el último intento seléucida de recuperar Irán y Mesopotamia.|Phraates gave him a king’s funeral and married a daughter of Demetrius II whom Antiochus had brought with him (Justin 38.10.10). It was the last Seleucid attempt to recover Iran and Mesopotamia.',acc:[]}
]},

/* ---------- Caná, c. 84 ---------- */
cana:{fases:[
 {t:'Aretas reaparece|Aretas reappears',f:'f',src:'jos13391',
  c:'Toda la batalla cabe en una frase de Josefo. El rey nabateo se retira primero y luego aparece de pronto con diez mil jinetes. Cómo se desplegaron no lo sabemos: aquí la caballería nabatea cae sobre las dos alas.|The whole battle fits in one sentence of Josephus. The Nabataean king withdraws at first and then suddenly appears with ten thousand horsemen. How they deployed we do not know: here the Nabataean cavalry falls on both wings.',
  acc:[['mv',['B2',4,5],['B3',6,5],['B9',11,5],['B10',13,5],['B1',2,5],['B11',14,5]]]},
 {t:'Antíoco combate con firmeza|Antiochus fights stoutly',f:'m',src:null,
  c:'Antíoco les sale al encuentro, combate «con firmeza» y empieza a vencer. En qué parte del campo, Josefo no lo dice.|Antiochus goes to meet them, fights “stoutly” and begins to win. In what part of the field, Josephus does not say.',
  acc:[['mv',['A8',11,6],['A0',10,6]],['at','A8','B9',5,{push:1,cine:1}],['at','B11','A9',2],['mv',['A0',11,5]],['at','A0','B9',4],['out','B9','fled']]},
 {t:'Acude al ala en apuros y cae|He goes to the hard-pressed wing and falls',f:'m',src:null,
  c:'Cuando ya vence, una parte de su ejército flaquea. El rey acude en su ayuda y muere allí.|When he is already winning, part of his army falters. The king goes to its aid and dies there.',
  acc:[['mv',['B2',4,6],['B3',5,6]],['at','B2','A1',4],['at','B3','A2',5],['out','A2','fled'],
       ['mv',['A0',6,6]],['at','A0','B3',4,{c:1}],['mv',['B5',6,5]],['at','B5','A0',5,{st:3,cine:1}],['at','B3','A0',4]]},
 {t:'La huida a Caná|The flight to Cana',f:'f',src:null,
  c:'Muerto el rey, el ejército huye a la aldea de Caná, donde la mayoría muere de hambre. Aretas III fue llamado poco después a reinar en Damasco (Josefo, Antigüedades judías 13.392).|With the king dead, the army flees to the village of Cana, where most die of hunger. Aretas III was soon afterwards called to rule at Damascus (Josephus, Jewish Antiquities 13.392).',
  acc:[['out','A1','fled'],['out','A3','fled'],['out','A4','fled'],['out','A5','fled'],['out','A6','fled'],['out','A7','fled'],['out','A8','fled'],['out','A9','fled']]}
]}
};
